// Plus Two entrance chemistry bank: Ionic equilibrium (Class 11). Original fibub questions.
// Data used: Kw = 1.0e-14 at 298 K; log 2 = 0.301, log 3 = 0.477, log 5 = 0.699; pKa (CH3COOH) = 4.74 (Ka = 1.8e-5), pKb (NH3) = 4.74 unless the question gives other values.
import { pick, int, choose, fmt, shuffleOpts, numOpts } from '../_entrance.js';

let _n = 0;
const EX = { 1: ['keam', 'cusat', 'comedk', 'jee-main', 'neet'], 2: ['keam', 'cusat', 'comedk', 'jee-main', 'neet'], 3: ['jee-main', 'neet', 'comedk'], 4: ['jee-main', 'jee-adv', 'neet'], 5: ['jee-adv'] };
const A4 = ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'];
const S4 = ['Both Statement I and Statement II are correct', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct', 'Both Statement I and Statement II are incorrect'];
const mk = (id, level, sub, q, right, wrongs, sol, trap) => {
  const pos = (_n++) % 4; const options = [...wrongs]; options.splice(pos, 0, right);
  return { id, type: 'mcq', level, format: 'single', exams: EX[level], sub, q, options, answer: pos, sol, ...(trap ? { trap } : {}) };
};
const nat = (id, level, sub, q, answer, tol, unit, sol, trap, calc) => ({ id, type: 'nat', level, format: tol === 0 ? 'integer' : 'numeric', exams: EX[level], sub, q, answer, tol, ...(unit ? { unit } : {}), sol, ...(trap ? { trap } : {}), ...(calc ? { calc } : {}) });
const msq = (id, level, sub, q, options, answer, sol, trap) => ({ id, type: 'msq', level, format: 'multi', exams: level >= 4 ? ['jee-adv'] : ['jee-adv', 'jee-main'], sub, q, options, answer, sol, ...(trap ? { trap } : {}) });
const asr = (id, level, sub, A, R, answer, sol, trap) => ({ id, type: 'mcq', level, format: 'assertion', exams: EX[level], sub, q: `<p><b>Assertion (A):</b> ${A}</p><p><b>Reason (R):</b> ${R}</p>`, options: A4, answer, sol, ...(trap ? { trap } : {}) });
const stm = (id, level, sub, s1, s2, answer, sol, trap) => ({ id, type: 'mcq', level, format: 'statements', exams: EX[level], sub, q: `<p><b>Statement I:</b> ${s1}</p><p><b>Statement II:</b> ${s2}</p>`, options: S4, answer, sol, ...(trap ? { trap } : {}) });
const mat = (id, level, sub, group, q, right, wrongs, sol, trap) => ({ ...mk(id, level, sub, q, right, wrongs, sol, trap), format: 'match', group });
const P = (id, level, sub, group, q, right, wrongs, sol, trap) => ({ ...mk(id, level, sub, q, right, wrongs, sol, trap), format: 'passage', group });
const PN = (id, level, sub, group, q, answer, tol, unit, sol, trap, calc) => ({ ...nat(id, level, sub, q, answer, tol, unit, sol, trap, calc), format: 'passage', group });

const l10 = Math.log10;

// shared match helper (pasted into each ext)
const XGR = {};
const M = (id, level, sub, title, l1, l2, map, sol, trap) => {
  const L = 'ABCD', Q = 'pqrst';
  XGR[id] = { title, list1: l1.map((t, i) => `${L[i]}. ${t}`), list2: l2.map((t, i) => `${Q[i]}. ${t}`) };
  const code = (m) => m.map((x, i) => `${L[i]}-${x}`).join(', ');
  const sw = (a, i, j) => { const b = [...a]; [b[i], b[j]] = [b[j], b[i]]; return b; };
  const wr = [sw(map, 0, 1), sw(map, 1, 2), sw(map, 2, 3), sw(map, 0, 3), sw(map, 0, 2)].map(code).filter((c) => c !== code(map));
  return mat(id, level, sub, id, 'Match the entries of List I with those of List II and choose the correct code.', code(map), wr.slice(0, 3), sol, trap);
};
const XI = [
  mk('ie-x01', 2, 'pH of strong acid', 'The pH of 0.010 M HCl at 25 &deg;C is', '2', ['1', '3', '12'], '<p>HCl is a strong acid, so [H<sup>+</sup>] = 0.010 = 10<sup>-2</sup> M and pH = <b>2</b>.</p>'),
  nat('ie-x02', 2, 'pH of strong base', 'The pH of 0.0010 M NaOH at 25 &deg;C is', 11, 0, '', '<p>[OH<sup>-</sup>] = 10<sup>-3</sup>, so pOH = 3 and pH = 14 - 3 = <b>11</b>.</p>'),
  mk('ie-x03', 2, 'conjugate pairs', 'The conjugate base of H<sub>2</sub>PO<sub>4</sub><sup>-</sup> is', 'HPO<sub>4</sub><sup>2-</sup>', ['H<sub>3</sub>PO<sub>4</sub>', 'PO<sub>4</sub><sup>3-</sup>', 'H<sub>3</sub>O<sup>+</sup>'], '<p>The conjugate base is formed by <i>removing one proton</i>: H<sub>2</sub>PO<sub>4</sub><sup>-</sup> &rarr; HPO<sub>4</sub><sup>2-</sup> + H<sup>+</sup>. H<sub>3</sub>PO<sub>4</sub> is the conjugate acid.</p>'),
  mk('ie-x04', 2, 'salt hydrolysis', 'Which salt gives an acidic aqueous solution?', 'NH<sub>4</sub>Cl', ['NaCl', 'CH<sub>3</sub>COONa', 'KNO<sub>3</sub>'], '<p>NH<sub>4</sub>Cl is the salt of a weak base (NH<sub>3</sub>) and a strong acid (HCl). NH<sub>4</sub><sup>+</sup> hydrolyses: NH<sub>4</sub><sup>+</sup> + H<sub>2</sub>O &#8652; NH<sub>3</sub> + H<sub>3</sub>O<sup>+</sup>. NaCl and KNO<sub>3</sub> are neutral; CH<sub>3</sub>COONa is basic.</p>'),
  nat('ie-x05', 2, 'polyprotic strong acid', 'The pH of 0.050 M H<sub>2</sub>SO<sub>4</sub>, assuming both protons ionise completely, is', 1, 0, '', '<p>[H<sup>+</sup>] = 2 &times; 0.050 = 0.10 M, so pH = <b>1</b>.</p>', 'Forgetting the second proton gives pH 1.3.'),
  mk('ie-x06', 2, 'solubility product', 'The solubility product expression for Ca<sub>3</sub>(PO<sub>4</sub>)<sub>2</sub> is', '[Ca<sup>2+</sup>]<sup>3</sup>[PO<sub>4</sub><sup>3-</sup>]<sup>2</sup>', ['[Ca<sup>2+</sup>]<sup>2</sup>[PO<sub>4</sub><sup>3-</sup>]<sup>3</sup>', '[Ca<sup>2+</sup>][PO<sub>4</sub><sup>3-</sup>]', '[Ca<sub>3</sub>(PO<sub>4</sub>)<sub>2</sub>]'], '<p>Ca<sub>3</sub>(PO<sub>4</sub>)<sub>2</sub>(s) &#8652; 3Ca<sup>2+</sup> + 2PO<sub>4</sub><sup>3-</sup>. Each ion is raised to its coefficient; the pure solid is left out.</p>'),

  nat('ie-x07', 3, 'pH of weak acid', 'The pH of 0.10 M CH<sub>3</sub>COOH (K<sub>a</sub> = 1.8 &times; 10<sup>-5</sup>) is', 2.87, 0.02, '', '<p>[H<sup>+</sup>] = &radic;(K<sub>a</sub>c) = &radic;(1.8 &times; 10<sup>-5</sup> &times; 0.10) = &radic;(1.8 &times; 10<sup>-6</sup>) = 1.34 &times; 10<sup>-3</sup> M.</p><p>pH = -log(1.34 &times; 10<sup>-3</sup>) = <b>2.87</b>.</p>'),
  nat('ie-x08', 3, 'pH of weak base', 'The pH of 0.10 M NH<sub>3</sub> (K<sub>b</sub> = 1.8 &times; 10<sup>-5</sup>) is', 11.13, 0.02, '', '<p>[OH<sup>-</sup>] = &radic;(K<sub>b</sub>c) = 1.34 &times; 10<sup>-3</sup> M, so pOH = 2.87 and pH = 14 - 2.87 = <b>11.13</b>.</p>'),
  nat('ie-x09', 3, 'Henderson equation', 'A buffer contains 0.20 M CH<sub>3</sub>COOH and 0.10 M CH<sub>3</sub>COONa. If pK<sub>a</sub> = 4.74, its pH is', 4.44, 0.02, '', '<p>pH = pK<sub>a</sub> + log([salt]/[acid]) = 4.74 + log(0.10/0.20) = 4.74 - 0.30 = <b>4.44</b>.</p>', 'Put the salt (base) on top, the acid below.'),
  nat('ie-x10', 3, 'salt hydrolysis', 'The pH of 0.10 M CH<sub>3</sub>COONa (K<sub>a</sub> of acetic acid = 1.8 &times; 10<sup>-5</sup>) is', 8.87, 0.02, '', '<p>K<sub>h</sub> = K<sub>w</sub>/K<sub>a</sub> = 10<sup>-14</sup>/(1.8 &times; 10<sup>-5</sup>) = 5.56 &times; 10<sup>-10</sup>.</p><p>[OH<sup>-</sup>] = &radic;(K<sub>h</sub>c) = &radic;(5.56 &times; 10<sup>-11</sup>) = 7.45 &times; 10<sup>-6</sup>, so pOH = 5.13 and pH = <b>8.87</b>.</p>'),
  nat('ie-x11', 3, 'solubility product', 'K<sub>sp</sub> of Mg(OH)<sub>2</sub> is 4.0 &times; 10<sup>-12</sup>. Its saturated solution has [OH<sup>-</sup>] = x &times; 10<sup>-4</sup> M. The value of x is', 2, 0, '', '<p>Mg(OH)<sub>2</sub> &#8652; Mg<sup>2+</sup> + 2OH<sup>-</sup>. With solubility s, K<sub>sp</sub> = s(2s)<sup>2</sup> = 4s<sup>3</sup>.</p><p>s<sup>3</sup> = 10<sup>-12</sup>, so s = 10<sup>-4</sup> M and [OH<sup>-</sup>] = 2s = 2 &times; 10<sup>-4</sup>. So x = <b>2</b>.</p>', 'Do not forget that [OH<sup>-</sup>] is twice the solubility.'),
  mk('ie-x12', 3, 'buffer solutions', 'Which mixture is a buffer?', 'CH<sub>3</sub>COOH + CH<sub>3</sub>COONa', ['HCl + NaCl', 'NaOH + NaCl', 'HNO<sub>3</sub> + KNO<sub>3</sub>'], '<p>A buffer needs a weak acid with its conjugate base (or a weak base with its conjugate acid), so both added acid and added base can be absorbed. The other mixtures contain a strong acid or strong base, with an ion that cannot react with added H<sup>+</sup> or OH<sup>-</sup>.</p>'),
  asr('ie-x13', 3, 'salt hydrolysis', 'An aqueous solution of NaCl is neutral at 25 &deg;C.', 'Neither Na<sup>+</sup> (from a strong base) nor Cl<sup>-</sup> (from a strong acid) reacts with water.', 0, '<p>Na<sup>+</sup> is the conjugate acid of the very strong base NaOH and Cl<sup>-</sup> is the conjugate base of the strong acid HCl; both are too weak to accept or donate protons. So [H<sup>+</sup>] = [OH<sup>-</sup>] = 10<sup>-7</sup>. R explains A.</p>'),
  stm('ie-x14', 3, 'very dilute solutions', 'The pH of 1.0 &times; 10<sup>-8</sup> M HCl at 25 &deg;C is 8.', 'In very dilute acid, the H<sup>+</sup> from water has to be counted too.', 2, '<p>Statement I is wrong: an acid cannot give a basic solution. Water supplies about 10<sup>-7</sup> M of H<sup>+</sup>, and the total [H<sup>+</sup>] is a little above that, so pH is about 6.98. Statement II is correct.</p>'),
  M('ie-x15', 3, 'salt hydrolysis', 'Match the salt with the nature of its solution', ['NH<sub>4</sub>Cl', 'CH<sub>3</sub>COONa', 'NaCl', 'CH<sub>3</sub>COONH<sub>4</sub>'], ['Basic, anion hydrolyses', 'Neutral, both ions hydrolyse to the same extent', 'Neutral, neither ion hydrolyses', 'Acidic, cation hydrolyses'], ['s', 'p', 'r', 'q'], '<p>NH<sub>4</sub>Cl: weak base and strong acid, so acidic (s). CH<sub>3</sub>COONa: basic (p). NaCl: neutral with no hydrolysis (r). Ammonium acetate: K<sub>a</sub> of acetic acid is nearly equal to K<sub>b</sub> of ammonia, so the two hydrolyses cancel and pH is about 7 (q).</p>'),
  M('ie-x16', 4, 'solubility product', 'Match the salt with the expression for its solubility s in terms of K<sub>sp</sub>', ['AgCl', 'Ca<sub>3</sub>(PO<sub>4</sub>)<sub>2</sub>', 'Al(OH)<sub>3</sub>', 'Ag<sub>2</sub>CrO<sub>4</sub>'], ['(K<sub>sp</sub>/27)<sup>1/4</sup>', '(K<sub>sp</sub>/4)<sup>1/3</sup>', '(K<sub>sp</sub>/108)<sup>1/5</sup>', '&radic;K<sub>sp</sub>'], ['s', 'r', 'p', 'q'], '<p>AgCl: K<sub>sp</sub> = s<sup>2</sup> (s). Ca<sub>3</sub>(PO<sub>4</sub>)<sub>2</sub>: (3s)<sup>3</sup>(2s)<sup>2</sup> = 108s<sup>5</sup> (r). Al(OH)<sub>3</sub>: s(3s)<sup>3</sup> = 27s<sup>4</sup> (p). Ag<sub>2</sub>CrO<sub>4</sub>: (2s)<sup>2</sup>s = 4s<sup>3</sup> (q).</p>'),
  PN('ie-x17', 3, 'salt hydrolysis', 'x1', 'The hydrolysis constant K<sub>h</sub> of NH<sub>4</sub><sup>+</sup> is (in units of 10<sup>-10</sup>)', 5.56, 0.05, '&times; 10<sup>-10</sup>', '<p>K<sub>h</sub> = K<sub>w</sub>/K<sub>b</sub> = 10<sup>-14</sup>/(1.8 &times; 10<sup>-5</sup>) = <b>5.56 &times; 10<sup>-10</sup></b>.</p>'),
  PN('ie-x18', 4, 'salt hydrolysis', 'x1', 'The pH of 0.10 M NH<sub>4</sub>Cl is', 5.13, 0.02, '', '<p>[H<sup>+</sup>] = &radic;(K<sub>h</sub>c) = &radic;(5.56 &times; 10<sup>-10</sup> &times; 0.10) = 7.45 &times; 10<sup>-6</sup> M.</p><p>pH = <b>5.13</b>.</p>'),
  P('ie-x19', 4, 'degree of hydrolysis', 'x1', 'The degree of hydrolysis of NH<sub>4</sub><sup>+</sup> in 0.10 M NH<sub>4</sub>Cl is about', '7.5 &times; 10<sup>-5</sup>', ['7.5 &times; 10<sup>-6</sup>', '5.6 &times; 10<sup>-10</sup>', '1.34 &times; 10<sup>-3</sup>'], '<p>h = [H<sup>+</sup>]/c = 7.45 &times; 10<sup>-6</sup>/0.10 = <b>7.5 &times; 10<sup>-5</sup></b>. Check: h = &radic;(K<sub>h</sub>/c) = &radic;(5.56 &times; 10<sup>-9</sup>) = 7.5 &times; 10<sup>-5</sup>.</p>', '7.5 &times; 10<sup>-6</sup> is the [H<sup>+</sup>], not the degree of hydrolysis.'),
  mk('ie-x20', 3, 'amphiprotic species', 'The pH of 0.1 M NaHCO<sub>3</sub> is closest to (pK<sub>a1</sub> = 6.35 and pK<sub>a2</sub> = 10.33 of H<sub>2</sub>CO<sub>3</sub>)', '8.3', ['6.4', '10.3', '12.0'], '<p>HCO<sub>3</sub><sup>-</sup> is amphiprotic; for such a species pH &asymp; &frac12;(pK<sub>a1</sub> + pK<sub>a2</sub>) = &frac12;(6.35 + 10.33) = <b>8.34</b>, nearly independent of concentration.</p>'),
  M('ie-x21', 3, 'mixing acid and base', 'Equal volumes of 0.1 M solutions (or the stated ratio) are mixed. Match the mixture with the result', ['HCl + NaOH', 'CH<sub>3</sub>COOH + NaOH', 'NH<sub>3</sub> + HCl', '2 volumes of HCl + 1 volume of NaOH'], ['pH exactly 7', 'pH above 7 (anion hydrolysis)', 'pH below 7 (cation hydrolysis)', 'pH below 7 because of excess strong acid'], ['p', 'q', 'r', 's'], '<p>HCl + NaOH gives NaCl: neutral (p). CH<sub>3</sub>COOH + NaOH gives CH<sub>3</sub>COONa: basic (q). NH<sub>3</sub> + HCl gives NH<sub>4</sub>Cl: acidic by hydrolysis (r). With 2 HCl : 1 NaOH, half of the acid remains unneutralised (s).</p>'),

  nat('ie-x22', 4, 'mixing acid and base', '100 mL of 0.10 M HCl is mixed with 50 mL of 0.10 M NaOH. The pH of the mixture is', 1.48, 0.02, '', '<p>mmol H<sup>+</sup> = 10; mmol OH<sup>-</sup> = 5. Excess H<sup>+</sup> = 5 mmol in 150 mL.</p><p>[H<sup>+</sup>] = 5/150 = 0.0333 M, pH = <b>1.48</b>.</p>', 'Divide by the total volume, 150 mL, not 100 mL.'),
  nat('ie-x23', 4, 'very dilute solutions', 'The pH of 1.0 &times; 10<sup>-8</sup> M HCl at 25 &deg;C, counting the H<sup>+</sup> from water, is', 6.98, 0.01, '', '<p>[H<sup>+</sup>] = c + [OH<sup>-</sup>] = 10<sup>-8</sup> + K<sub>w</sub>/[H<sup>+</sup>].</p><p>[H<sup>+</sup>]<sup>2</sup> - 10<sup>-8</sup>[H<sup>+</sup>] - 10<sup>-14</sup> = 0, giving [H<sup>+</sup>] = (10<sup>-8</sup> + &radic;(10<sup>-16</sup> + 4 &times; 10<sup>-14</sup>))/2 = 1.05 &times; 10<sup>-7</sup>.</p><p>pH = <b>6.98</b>.</p>'),
  nat('ie-x24', 4, 'precipitation', 'K<sub>sp</sub> of AgCl is 1.0 &times; 10<sup>-10</sup> (taken as exact for this question). Precipitation starts from a solution with [Ag<sup>+</sup>] = 0.010 M when pCl = -log[Cl<sup>-</sup>] reaches', 8, 0, '', '<p>Precipitation starts when [Ag<sup>+</sup>][Cl<sup>-</sup>] = K<sub>sp</sub>: [Cl<sup>-</sup>] = 10<sup>-10</sup>/10<sup>-2</sup> = 10<sup>-8</sup> M, so pCl = <b>8</b>.</p>'),
  nat('ie-x25', 4, 'salt hydrolysis', 'How many of these give an acidic aqueous solution: NH<sub>4</sub>Cl, AlCl<sub>3</sub>, Na<sub>2</sub>CO<sub>3</sub>, KNO<sub>3</sub>, FeCl<sub>3</sub>, CH<sub>3</sub>COONa?', 3, 0, '', '<p>NH<sub>4</sub>Cl, AlCl<sub>3</sub> and FeCl<sub>3</sub> contain cations of weak bases (NH<sub>3</sub>, Al(OH)<sub>3</sub>, Fe(OH)<sub>3</sub>) with a strong acid anion: acidic. Na<sub>2</sub>CO<sub>3</sub> and CH<sub>3</sub>COONa are basic; KNO<sub>3</sub> is neutral. Count: <b>3</b>.</p>'),
  nat('ie-x26', 4, 'buffer after adding acid', '1.0 L of a buffer has 0.20 mol CH<sub>3</sub>COOH and 0.20 mol CH<sub>3</sub>COONa (pK<sub>a</sub> = 4.74). 0.050 mol of HCl is added (no volume change). The new pH is', 4.52, 0.02, '', '<p>HCl converts acetate to acetic acid: CH<sub>3</sub>COO<sup>-</sup> = 0.20 - 0.05 = 0.15 mol; CH<sub>3</sub>COOH = 0.20 + 0.05 = 0.25 mol.</p><p>pH = 4.74 + log(0.15/0.25) = 4.74 - 0.22 = <b>4.52</b>.</p>'),
  mk('ie-x27', 4, 'buffer capacity', 'A buffer made from a weak acid HA and its salt has the greatest buffer capacity when', '[HA] = [A<sup>-</sup>], that is, pH = pK<sub>a</sub>', ['[HA] is ten times [A<sup>-</sup>]', 'pH = 7', '[A<sup>-</sup>] is ten times [HA]'], '<p>The buffer resists added acid or base best when both components are present in large and equal amounts (ratio 1:1), where pH = pK<sub>a</sub>. The useful range is about pK<sub>a</sub> &plusmn; 1.</p>'),
  msq('ie-x28', 4, 'buffer solutions', '<p>Which of these are buffers?</p>', ['CH<sub>3</sub>COOH + CH<sub>3</sub>COONa', 'HCl + NaCl', 'NH<sub>3</sub> + NH<sub>4</sub>Cl', '100 mL 0.10 M CH<sub>3</sub>COOH + 50 mL 0.10 M NaOH'], [0, 2, 3], '<p>A and C are weak acid/base with their conjugates. D: NaOH converts half the acetic acid into acetate (5 mmol each), giving a buffer. B has a strong acid, so it is not a buffer.</p>'),
  msq('ie-x29', 4, 'salt hydrolysis', '<p>Which aqueous solutions (0.1 M) have pH greater than 7?</p>', ['Na<sub>2</sub>CO<sub>3</sub>', 'NH<sub>4</sub>Cl', 'KNO<sub>3</sub>', 'CH<sub>3</sub>COOK'], [0, 3], '<p>Carbonate and acetate are conjugate bases of weak acids, so they take protons from water and give OH<sup>-</sup>. NH<sub>4</sub>Cl is acidic; KNO<sub>3</sub> is neutral.</p>'),
  msq('ie-x30', 4, 'Lewis concept', '<p>Which are Lewis acids?</p>', ['BF<sub>3</sub>', 'NH<sub>3</sub>', 'Ag<sup>+</sup>', 'CN<sup>-</sup>'], [0, 2], '<p>A Lewis acid accepts an electron pair. BF<sub>3</sub> has an empty p orbital; Ag<sup>+</sup> has empty orbitals and forms complexes. NH<sub>3</sub> and CN<sup>-</sup> have lone pairs to donate: Lewis bases.</p>'),
  msq('ie-x31', 4, 'solubility product', '<p>Which statements are correct?</p>', ['For AgCl and AgBr, the one with the smaller K<sub>sp</sub> is the less soluble', 'The K<sub>sp</sub> values of AgCl and Ag<sub>2</sub>CrO<sub>4</sub> can be compared directly to decide which is more soluble', 'Adding a common ion decreases the solubility of a sparingly soluble salt', 'Adding a common ion decreases K<sub>sp</sub>'], [0, 2], '<p>Comparing K<sub>sp</sub> works only for salts of the same type (same ion ratio). A common ion shifts the dissolution equilibrium backward, lowering solubility, while K<sub>sp</sub> stays constant at fixed temperature.</p>'),
  msq('ie-x32', 4, 'amphiprotic species', '<p>Which species are amphiprotic?</p>', ['HCO<sub>3</sub><sup>-</sup>', 'NH<sub>4</sub><sup>+</sup>', 'H<sub>2</sub>PO<sub>4</sub><sup>-</sup>', 'Cl<sup>-</sup>'], [0, 2], '<p>HCO<sub>3</sub><sup>-</sup> and H<sub>2</sub>PO<sub>4</sub><sup>-</sup> can both give up and accept a proton. NH<sub>4</sub><sup>+</sup> can only donate; Cl<sup>-</sup> can only accept (very weakly).</p>'),
  nat('ie-x33', 4, 'Ostwald dilution law', 'A weak acid HA has K<sub>a</sub> = 1.0 &times; 10<sup>-5</sup>. Its percentage ionisation in 0.010 M solution is', 3.16, 0.05, '%', '<p>&alpha; = &radic;(K<sub>a</sub>/c) = &radic;(10<sup>-5</sup>/0.010) = &radic;(10<sup>-3</sup>) = 0.0316 = <b>3.16%</b>.</p>'),
  nat('ie-x34', 4, 'ionic product of water', 'At a certain temperature K<sub>w</sub> = 1.0 &times; 10<sup>-13</sup>. The pH of pure water at this temperature is', 6.5, 0.01, '', '<p>In pure water [H<sup>+</sup>] = [OH<sup>-</sup>] = &radic;(10<sup>-13</sup>) = 10<sup>-6.5</sup>, so pH = <b>6.5</b>. The water is still neutral.</p>', 'pH below 7 does not mean acidic when K<sub>w</sub> changes.'),
  nat('ie-x35', 4, 'salt hydrolysis', '100 mL of 0.10 M CH<sub>3</sub>COOH is mixed with 100 mL of 0.10 M NaOH. (pK<sub>a</sub> = 4.74.) The pH is', 8.72, 0.02, '', '<p>The two neutralise exactly, giving 0.010 mol CH<sub>3</sub>COONa in 200 mL, c = 0.050 M.</p><p>pH = 7 + &frac12;(pK<sub>a</sub> + log c) = 7 + &frac12;(4.74 - 1.30) = <b>8.72</b>.</p>'),
  nat('ie-x36', 4, 'pH of strong base', 'The pH of 0.0050 M Ba(OH)<sub>2</sub> at 25 &deg;C is', 12, 0, '', '<p>Each Ba(OH)<sub>2</sub> gives two OH<sup>-</sup>: [OH<sup>-</sup>] = 0.010 M, pOH = 2, pH = <b>12</b>.</p>'),
  nat('ie-x37', 4, 'solubility product', 'K<sub>sp</sub> of Ca<sub>3</sub>(PO<sub>4</sub>)<sub>2</sub> is 1.08 &times; 10<sup>-23</sup>. Its solubility s = 10<sup>-n</sup> mol L<sup>-1</sup>. The value of n is', 5, 0, '', '<p>K<sub>sp</sub> = (3s)<sup>3</sup>(2s)<sup>2</sup> = 108s<sup>5</sup>, so s<sup>5</sup> = 1.08 &times; 10<sup>-23</sup>/108 = 10<sup>-25</sup> and s = 10<sup>-5</sup>. n = <b>5</b>.</p>'),
  nat('ie-x38', 4, 'common ion effect on solubility', 'K<sub>sp</sub> of AgCl is 1.8 &times; 10<sup>-10</sup>. Its solubility in 0.010 M NaCl is x &times; 10<sup>-8</sup> mol L<sup>-1</sup>. The value of x is', 1.8, 0.05, '', '<p>s = [Ag<sup>+</sup>] = K<sub>sp</sub>/[Cl<sup>-</sup>] = 1.8 &times; 10<sup>-10</sup>/0.010 = 1.8 &times; 10<sup>-8</sup> M (the Cl<sup>-</sup> from AgCl is negligible). x = <b>1.8</b>. In pure water it would be 1.3 &times; 10<sup>-5</sup>.</p>'),
  asr('ie-x39', 4, 'amphiprotic species', 'An aqueous solution of NaHCO<sub>3</sub> is basic.', 'HCO<sub>3</sub><sup>-</sup> hydrolyses (K<sub>h</sub> = K<sub>w</sub>/K<sub>a1</sub> = 2.2 &times; 10<sup>-8</sup>) more than it ionises (K<sub>a2</sub> = 4.7 &times; 10<sup>-11</sup>).', 0, '<p>HCO<sub>3</sub><sup>-</sup> + H<sub>2</sub>O &#8652; H<sub>2</sub>CO<sub>3</sub> + OH<sup>-</sup> (K<sub>h</sub> = 2.2 &times; 10<sup>-8</sup>) beats HCO<sub>3</sub><sup>-</sup> &#8652; H<sup>+</sup> + CO<sub>3</sub><sup>2-</sup> (K<sub>a2</sub> = 4.7 &times; 10<sup>-11</sup>). Net OH<sup>-</sup>: basic, with pH about 8.3. R explains A.</p>'),
  { ...mk('ie-x40', 4, 'mixed counting', '<p>How many of the following are correct?</p><p>(1) The pH of 0.1 M HCl is 1.<br>(2) The pH of 10<sup>-8</sup> M HCl is 8.<br>(3) For a conjugate acid-base pair in water at 25 &deg;C, pK<sub>a</sub> + pK<sub>b</sub> = 14.<br>(4) The pH of a buffer changes greatly when it is diluted ten times.</p>', '2', ['1', '3', '4'], '<p>(1) true. (2) false: it is about 6.98. (3) true. (4) false: pH = pK<sub>a</sub> + log([A<sup>-</sup>]/[HA]) depends on the ratio, which does not change on dilution (capacity falls, the pH hardly moves). So <b>2</b>.</p>'), format: 'statements' },
  M('ie-x41', 4, 'pH formulae', 'Match the solution (concentration c) with the pH formula', ['Weak acid HA', 'Weak base B', 'Salt of a weak acid and a strong base', 'Salt of a weak base and a strong acid'], ['7 - &frac12;(pK<sub>b</sub> + log c)', '&frac12;(pK<sub>a</sub> - log c)', '7 + &frac12;(pK<sub>a</sub> + log c)', '14 - &frac12;(pK<sub>b</sub> - log c)'], ['q', 's', 'r', 'p'], '<p>Weak acid: [H<sup>+</sup>] = &radic;(K<sub>a</sub>c), pH = &frac12;(pK<sub>a</sub> - log c) (q). Weak base: pOH = &frac12;(pK<sub>b</sub> - log c), so pH = 14 - &frac12;(pK<sub>b</sub> - log c) (s). Salt of weak acid: pH = 7 + &frac12;(pK<sub>a</sub> + log c) (r). Salt of weak base: pH = 7 - &frac12;(pK<sub>b</sub> + log c) (p).</p>'),
  M('ie-x42', 2, 'conjugate pairs', 'Match each species with its conjugate acid', ['NH<sub>3</sub>', 'H<sub>2</sub>O', 'HCO<sub>3</sub><sup>-</sup>', 'HSO<sub>4</sub><sup>-</sup>'], ['H<sub>3</sub>O<sup>+</sup>', 'NH<sub>4</sub><sup>+</sup>', 'H<sub>2</sub>CO<sub>3</sub>', 'H<sub>2</sub>SO<sub>4</sub>'], ['q', 'p', 'r', 's'], '<p>The conjugate acid has one more proton: NH<sub>3</sub> &rarr; NH<sub>4</sub><sup>+</sup> (q); H<sub>2</sub>O &rarr; H<sub>3</sub>O<sup>+</sup> (p); HCO<sub>3</sub><sup>-</sup> &rarr; H<sub>2</sub>CO<sub>3</sub> (r); HSO<sub>4</sub><sup>-</sup> &rarr; H<sub>2</sub>SO<sub>4</sub> (s).</p>'),
  M('ie-x43', 5, 'titration curves', 'A weak acid HA (concentration c) is titrated with NaOH. Match the point on the curve with the pH expression', ['Before any NaOH is added', 'Half-way to the equivalence point', 'At the equivalence point (salt concentration c<sub>s</sub>)', 'After equivalence'], ['7 + &frac12;(pK<sub>a</sub> + log c<sub>s</sub>)', 'pH = pK<sub>a</sub>', '&frac12;(pK<sub>a</sub> - log c)', '14 + log[OH<sup>-</sup>]<sub>excess</sub>'], ['r', 'q', 'p', 's'], '<p>Start: only the weak acid, pH = &frac12;(pK<sub>a</sub> - log c) (r). Half-way: [HA] = [A<sup>-</sup>], so pH = pK<sub>a</sub> (q). Equivalence: only the salt A<sup>-</sup>, basic: 7 + &frac12;(pK<sub>a</sub> + log c<sub>s</sub>) (p). Beyond: excess strong base sets the pH (s).</p>'),
  M('ie-x44', 3, 'pH calculations', 'Match the 0.010 M solution with its pH (strong electrolytes, complete ionisation) at 25 &deg;C', ['HCl', 'H<sub>2</sub>SO<sub>4</sub>', 'NaOH', 'Ba(OH)<sub>2</sub>'], ['1.70', '2.00', '12.00', '12.30'], ['q', 'p', 'r', 's'], '<p>HCl: [H<sup>+</sup>] = 0.010, pH 2.00 (q is "2.00"). H<sub>2</sub>SO<sub>4</sub>: [H<sup>+</sup>] = 0.020, pH 1.70 (p). NaOH: pOH 2, pH 12.00 (r). Ba(OH)<sub>2</sub>: [OH<sup>-</sup>] = 0.020, pOH 1.70, pH 12.30 (s).</p>'),
  M('ie-x45', 2, 'acid-base theories', 'Match the term with its meaning', ['Arrhenius acid', 'Br&oslash;nsted&ndash;Lowry acid', 'Lewis acid', 'Amphiprotic species'], ['Electron-pair acceptor', 'Gives H<sup>+</sup> ions in water', 'Can donate and accept a proton', 'Proton donor'], ['q', 's', 'p', 'r'], '<p>Arrhenius: produces H<sup>+</sup> in water (q). Br&oslash;nsted&ndash;Lowry: proton donor (s). Lewis: electron-pair acceptor (p). Amphiprotic: both donates and accepts a proton (r).</p>'),
  PN('ie-x46', 4, 'basic buffer', 'x2', '100 mL of 0.20 M NH<sub>3</sub> is mixed with 100 mL of 0.10 M HCl. K<sub>b</sub> = 1.8 &times; 10<sup>-5</sup> (pK<sub>b</sub> = 4.74). The pH of the mixture is', 9.26, 0.02, '', '<p>Moles: NH<sub>3</sub> = 20 mmol, HCl = 10 mmol. They form 10 mmol NH<sub>4</sub><sup>+</sup>, leaving 10 mmol NH<sub>3</sub>: equal amounts, a buffer.</p><p>pOH = pK<sub>b</sub> + log([NH<sub>4</sub><sup>+</sup>]/[NH<sub>3</sub>]) = 4.74 + 0 = 4.74, so pH = <b>9.26</b>.</p>'),
  PN('ie-x47', 4, 'buffer after adding base', 'x2', '10 mL of 0.10 M NaOH is added to the buffer. The pH becomes', 9.35, 0.02, '', '<p>NaOH = 1.0 mmol converts NH<sub>4</sub><sup>+</sup> to NH<sub>3</sub>: NH<sub>4</sub><sup>+</sup> = 9.0 mmol, NH<sub>3</sub> = 11.0 mmol.</p><p>pOH = 4.74 + log(9/11) = 4.74 - 0.087 = 4.65, so pH = <b>9.35</b>.</p>'),
  P('ie-x48', 4, 'buffer dilution', 'x2', 'If the original buffer is diluted tenfold with water, its pH', 'stays almost the same, but its capacity falls', ['rises by 1', 'falls by 1', 'becomes 7'], '<p>pOH = pK<sub>b</sub> + log([NH<sub>4</sub><sup>+</sup>]/[NH<sub>3</sub>]); both concentrations fall tenfold, so the ratio is unchanged and so is the pH. With less base and acid present, it can absorb less added acid or base.</p>'),
  nat('ie-x49', 4, 'strong and weak acid mixtures', 'In a solution of 0.10 M HCl and 0.10 M CH<sub>3</sub>COOH (K<sub>a</sub> = 1.8 &times; 10<sup>-5</sup>), [CH<sub>3</sub>COO<sup>-</sup>] = y &times; 10<sup>-5</sup> M. The value of y is', 1.8, 0.05, '', '<p>[H<sup>+</sup>] is almost entirely from HCl: 0.10 M. K<sub>a</sub> = [H<sup>+</sup>][A<sup>-</sup>]/[HA], so [A<sup>-</sup>] = K<sub>a</sub>[HA]/[H<sup>+</sup>] = 1.8 &times; 10<sup>-5</sup> &times; 0.10/0.10 = 1.8 &times; 10<sup>-5</sup>. y = <b>1.8</b>. (In acetic acid alone it would be 1.3 &times; 10<sup>-3</sup>.)</p>'),
  nat('ie-x50', 5, 'selective precipitation', 'AgNO<sub>3</sub> is added slowly to a solution with 0.010 M Cl<sup>-</sup> and 0.010 M CrO<sub>4</sub><sup>2-</sup>. K<sub>sp</sub> (AgCl) = 1.8 &times; 10<sup>-10</sup>; K<sub>sp</sub> (Ag<sub>2</sub>CrO<sub>4</sub>) = 1.1 &times; 10<sup>-12</sup>. When Ag<sub>2</sub>CrO<sub>4</sub> just starts to precipitate, the percentage of the original Cl<sup>-</sup> already precipitated is', 99.83, 0.02, '%', '<p>Ag<sub>2</sub>CrO<sub>4</sub> starts when [Ag<sup>+</sup>] = &radic;(1.1 &times; 10<sup>-12</sup>/0.010) = 1.05 &times; 10<sup>-5</sup> M.</p><p>Then [Cl<sup>-</sup>] = 1.8 &times; 10<sup>-10</sup>/1.05 &times; 10<sup>-5</sup> = 1.72 &times; 10<sup>-5</sup> M, i.e. 0.17% of 0.010 M remains.</p><p>Precipitated: 100 - 0.17 = <b>99.83%</b>.</p>'),
  nat('ie-x51', 5, 'pH of weak acid', 'A 0.10 M solution of a weak acid HA has a pH of 3.0. The pK<sub>a</sub> of HA (nearest whole number) is', 5, 0, '', '<p>[H<sup>+</sup>] = 10<sup>-3</sup> = [A<sup>-</sup>]; [HA] &asymp; 0.10 - 0.001 = 0.099. K<sub>a</sub> = (10<sup>-3</sup>)<sup>2</sup>/0.099 = 1.0 &times; 10<sup>-5</sup>, so pK<sub>a</sub> = <b>5</b>.</p>'),
  nat('ie-x52', 5, 'Ostwald dilution law', 'A weak acid has K<sub>a</sub> = 1.0 &times; 10<sup>-6</sup>. The percentage ionised in 0.010 M solution is', 1, 0, '%', '<p>&alpha; = &radic;(K<sub>a</sub>/c) = &radic;(10<sup>-6</sup>/10<sup>-2</sup>) = &radic;(10<sup>-4</sup>) = 0.01, so <b>1%</b>.</p>'),
  nat('ie-x53', 5, 'precipitation and pH', 'Mg(OH)<sub>2</sub> (K<sub>sp</sub> = 1.0 &times; 10<sup>-11</sup>) just begins to precipitate from 0.10 M Mg<sup>2+</sup> at a pH of', 9, 0, '', '<p>[OH<sup>-</sup>]<sup>2</sup> = K<sub>sp</sub>/[Mg<sup>2+</sup>] = 10<sup>-11</sup>/10<sup>-1</sup> = 10<sup>-10</sup>, so [OH<sup>-</sup>] = 10<sup>-5</sup>, pOH = 5 and pH = <b>9</b>.</p>'),
  nat('ie-x54', 4, 'titration curves', 'What volume (mL) of 0.10 M NaOH must be added to 100 mL of 0.10 M CH<sub>3</sub>COOH to give a solution with pH = pK<sub>a</sub>?', 50, 0, 'mL', '<p>pH = pK<sub>a</sub> when [acid] = [salt], i.e. half of the acid is neutralised: 0.5 &times; 10 mmol = 5 mmol NaOH = <b>50 mL</b>.</p>'),
  nat('ie-x55', 5, 'solubility and pH', 'K<sub>sp</sub> of Mg(OH)<sub>2</sub> is 5.6 &times; 10<sup>-12</sup>. Its solubility in a buffer of pH 10.0, in mmol L<sup>-1</sup>, is', 0.56, 0.01, 'mmol L<sup>-1</sup>', '<p>pH 10 means [OH<sup>-</sup>] = 10<sup>-4</sup> M (fixed by the buffer). s = [Mg<sup>2+</sup>] = K<sub>sp</sub>/[OH<sup>-</sup>]<sup>2</sup> = 5.6 &times; 10<sup>-12</sup>/10<sup>-8</sup> = 5.6 &times; 10<sup>-4</sup> M = <b>0.56 mmol L<sup>-1</sup></b>.</p>'),
  nat('ie-x56', 5, 'polyprotic acids (quadratic)', 'The pH of 0.010 M H<sub>2</sub>SO<sub>4</sub>, taking the first ionisation as complete and K<sub>a2</sub> = 1.2 &times; 10<sup>-2</sup>, is', 1.84, 0.02, '', '<p>After step 1: [H<sup>+</sup>] = 0.010 and [HSO<sub>4</sub><sup>-</sup>] = 0.010. For step 2, let x ionise: K<sub>a2</sub> = (0.010 + x)x/(0.010 - x) = 0.012.</p><p>x<sup>2</sup> + 0.022x - 1.2 &times; 10<sup>-4</sup> = 0, so x = 4.52 &times; 10<sup>-3</sup>.</p><p>[H<sup>+</sup>] = 0.01452, pH = <b>1.84</b>.</p>', 'Ignoring the second ionisation gives 2.0; the second step is too strong to ignore.'),
  msq('ie-x57', 5, 'titration curves', '<p>A weak acid is titrated with a strong base. Which are correct?</p>', ['At half-equivalence pH = pK<sub>a</sub>', 'At equivalence pH = 7', 'Phenolphthalein is a suitable indicator', 'Methyl orange is a suitable indicator'], [0, 2], '<p>Half-way [HA] = [A<sup>-</sup>]. At equivalence the solution contains A<sup>-</sup>, so pH &gt; 7; the steep part of the curve lies in the basic range (about 7&ndash;10), which suits phenolphthalein (8.3&ndash;10). Methyl orange (3.1&ndash;4.4) changes too early.</p>'),
  msq('ie-x58', 5, 'solubility and pH', '<p>Which salts are more soluble in 0.1 M HCl than in water?</p>', ['AgCl', 'CaCO<sub>3</sub>', 'Mg(OH)<sub>2</sub>', 'AgI'], [1, 2], '<p>Carbonate and hydroxide are bases: H<sup>+</sup> removes CO<sub>3</sub><sup>2-</sup> (as HCO<sub>3</sub><sup>-</sup>, CO<sub>2</sub>) or OH<sup>-</sup> (as H<sub>2</sub>O), pulling the equilibrium forward. Cl<sup>-</sup> and I<sup>-</sup> are conjugate bases of strong acids and are not removed; AgCl is in fact slightly less soluble (common ion Cl<sup>-</sup>).</p>'),
  msq('ie-x59', 5, 'salt hydrolysis', '<p>For 0.1 M CH<sub>3</sub>COONH<sub>4</sub> (K<sub>a</sub> of acetic acid = K<sub>b</sub> of NH<sub>3</sub>), which are correct?</p>', ['The pH is about 7', 'Both ions hydrolyse', 'The pH is independent of concentration', 'The degree of hydrolysis is independent of concentration'], [0, 1, 2, 3], '<p>pH = 7 + &frac12;(pK<sub>a</sub> - pK<sub>b</sub>) = 7 here. Both ions hydrolyse (A, B). For a salt of a weak acid and a weak base, the hydrolysis degree h = &radic;K<sub>h</sub>/(1 + &radic;K<sub>h</sub>) with K<sub>h</sub> = K<sub>w</sub>/(K<sub>a</sub>K<sub>b</sub>), which has no c in it, so both pH and h are independent of concentration.</p>', 'Unlike salts of one weak ion, h does not fall on dilution.'),
  msq('ie-x60', 5, 'ionic product of water', '<p>Which statements about pure water are correct?</p>', ['pH + pOH = pK<sub>w</sub> at every temperature', 'Neutral water at 60 &deg;C has a pH below 7', 'Pure water at 60 &deg;C is acidic', 'K<sub>w</sub> increases with temperature'], [0, 1, 3], '<p>Ionisation of water is endothermic, so K<sub>w</sub> grows with T and neutral pH falls below 7 (about 6.5 at 60 &deg;C). Water stays neutral because [H<sup>+</sup>] = [OH<sup>-</sup>], not acidic.</p>'),
  msq('ie-x61', 5, 'polyprotic acids', '<p>Which are correct for phosphoric acid and its ions?</p>', ['K<sub>a1</sub> &gt; K<sub>a2</sub> &gt; K<sub>a3</sub>', 'H<sub>2</sub>PO<sub>4</sub><sup>-</sup> is amphiprotic', 'The pH of H<sub>3</sub>PO<sub>4</sub> solution is mainly fixed by its third ionisation', 'PO<sub>4</sub><sup>3-</sup> is the conjugate base of HPO<sub>4</sub><sup>2-</sup>'], [0, 1, 3], '<p>Each step is harder than the one before (the leaving proton must leave a more negative ion). The first ionisation supplies almost all the H<sup>+</sup>, so C is false.</p>'),
  asr('ie-x62', 4, 'buffers', 'Diluting a buffer 100 times changes its pH very little but lowers its buffer capacity.', 'The pH of a buffer depends on the ratio [A<sup>-</sup>]/[HA], which is unchanged by dilution.', 0, '<p>Both parts of the ratio fall by the same factor, so the pH (from the Henderson equation) is nearly unchanged. The capacity depends on the amounts of the components, which have fallen. R explains A.</p>'),
  stm('ie-x63', 4, 'common ion effect', 'The K<sub>sp</sub> of AgCl is lower in 0.10 M NaCl than in water.', 'The solubility of AgCl is lower in 0.10 M NaCl than in water.', 2, '<p>K<sub>sp</sub> depends only on temperature, so Statement I is incorrect. The common ion Cl<sup>-</sup> pushes the equilibrium back, lowering the solubility: Statement II is correct.</p>'),
  asr('ie-x64', 5, 'very dilute solutions', 'The pH of 1.0 &times; 10<sup>-7</sup> M HCl at 25 &deg;C is exactly 7.', 'In such a dilute acid, water ionisation also contributes to [H<sup>+</sup>].', 3, '<p>A is false: [H<sup>+</sup>] = c + [OH<sup>-</sup>] gives [H<sup>+</sup>] = 1.62 &times; 10<sup>-7</sup>, pH 6.79. R is true: that water term is the reason the simple pH = -log c fails. R is true, A is false.</p>'),
];
const XGR2 = {
  x1: { title: 'Ammonium chloride in water', passage: '<p>A student prepares 0.10 M NH<sub>4</sub>Cl at 25 &deg;C. For NH<sub>3</sub>, K<sub>b</sub> = 1.8 &times; 10<sup>-5</sup>. Take K<sub>w</sub> = 1.0 &times; 10<sup>-14</sup>.</p>' },
  x2: { title: 'An ammonia buffer', passage: '<p>A buffer is made by adding 100 mL of 0.10 M HCl to 100 mL of 0.20 M NH<sub>3</sub> solution (K<sub>b</sub> = 1.8 &times; 10<sup>-5</sup>; take pK<sub>b</sub> = 4.74).</p>' },
};
Object.assign(XGR, XGR2);
const XGN = [
  { id: 'ie-g15', type: 'nat', level: 3, exams: EX[3], sub: 'pH of weak acid',
    make(rng) {
      const pKa = choose(rng, [3.5, 4, 4.5, 5, 5.5]); const c = choose(rng, [0.1, 0.05, 0.2, 0.5]); const Ka = 10 ** -pKa;
      const pH = 0.5 * (pKa - l10(c)); const ans = +pH.toFixed(2);
      return { q: `Find the pH of a ${c} M solution of a weak acid with pK<sub>a</sub> = ${pKa} (ionisation is small).`, answer: ans, tol: 0.03, pKa, c,
        sol: `<p>[H<sup>+</sup>] = &radic;(K<sub>a</sub>c), so pH = &frac12;(pK<sub>a</sub> - log c) = &frac12;(${pKa} - (${l10(c).toFixed(3)})) = <b>${ans}</b>.</p>` };
    }, verify: (p) => 0.5 * (p.pKa - Math.log10(p.c)) },
  { id: 'ie-g16', type: 'nat', level: 4, exams: EX[4], sub: 'buffer after adding acid or base',
    make(rng) {
      const pKa = choose(rng, [4.74, 4.76, 7.2, 9.25]); const a = pick(rng, 0.1, 0.5, 0.1); const b = pick(rng, 0.1, 0.5, 0.1); const x = pick(rng, 0.01, 0.06, 0.01); const acid = rng() < 0.5;
      const B = acid ? b - x : b + x; const A = acid ? a + x : a - x; const pH = pKa + Math.log10(B / A); const ans = +pH.toFixed(2);
      return { q: `1.0 L of a buffer contains ${a} mol of a weak acid HA (pK<sub>a</sub> = ${pKa}) and ${b} mol of its sodium salt NaA. ${x} mol of ${acid ? 'HCl' : 'NaOH'} is added with no change in volume. Find the new pH.`, answer: ans, tol: 0.02, pKa, a, b, x, acid,
        sol: `<p>${acid ? 'HCl converts A<sup>-</sup> into HA' : 'NaOH converts HA into A<sup>-</sup>'}: [A<sup>-</sup>] = ${B.toFixed(3)}, [HA] = ${A.toFixed(3)}.</p><p>pH = ${pKa} + log(${B.toFixed(3)}/${A.toFixed(3)}) = <b>${ans}</b>.</p>` };
    }, verify: (p) => p.pKa + Math.log10((p.acid ? p.b - p.x : p.b + p.x) / (p.acid ? p.a + p.x : p.a - p.x)) },
  { id: 'ie-g17', type: 'nat', level: 3, exams: EX[3], sub: 'solubility product',
    make(rng) {
      const e = int(rng, 3, 6); const m = pick(rng, 1, 9, 1); const s = m * 10 ** -e; const type = choose(rng, [['AB', 1, 'AgCl-type'], ['AB<sub>2</sub>', 4, 'MX<sub>2</sub>'], ['A<sub>2</sub>B', 4, 'M<sub>2</sub>X']]);
      const pK = -l10(type[1] * s ** (type[1] === 1 ? 2 : 3)); const ans = +pK.toFixed(2);
      return { q: `The solubility of a sparingly soluble salt ${type[0]} is ${m} &times; 10<sup>-${e}</sup> mol L<sup>-1</sup>. Find pK<sub>sp</sub> (= -log K<sub>sp</sub>).`, answer: ans, tol: 0.03, m, e, f: type[1],
        sol: `<p>K<sub>sp</sub> = ${type[1] === 1 ? 's<sup>2</sup>' : '4s<sup>3</sup>'} with s = ${m} &times; 10<sup>-${e}</sup>.</p><p>K<sub>sp</sub> = ${fmt(type[1] * s ** (type[1] === 1 ? 2 : 3), 3)}, so pK<sub>sp</sub> = <b>${ans}</b>.</p>` };
    }, verify: (p) => -Math.log10(p.f * (p.m * 10 ** -p.e) ** (p.f === 1 ? 2 : 3)) },
  { id: 'ie-g18', type: 'nat', level: 4, exams: EX[4], sub: 'common ion effect on solubility',
    make(rng) {
      const pK = choose(rng, [8, 9, 10, 11, 12]); const c = choose(rng, [0.1, 0.01, 0.001]);
      const ans = +(pK + l10(c) * -1 * -1).toFixed(2); // pS = pKsp - pc ... computed below
      const pS = pK - (-l10(c));
      return { q: `K<sub>sp</sub> of a salt AB is 1 &times; 10<sup>-${pK}</sup>. Its solubility in ${c} M of a solution containing the common ion B<sup>-</sup> is s. Find pS = -log s.`, answer: +pS.toFixed(2), tol: 0.03, pK, c,
        sol: `<p>s = K<sub>sp</sub>/[B<sup>-</sup>] = 10<sup>-${pK}</sup>/${c} = 10<sup>-${pS.toFixed(0)}</sup>, so pS = <b>${pS.toFixed(2)}</b>.</p>` };
    }, verify: (p) => p.pK + Math.log10(p.c) },
  { id: 'ie-g19', type: 'nat', level: 4, exams: EX[4], sub: 'mixing acid and base',
    make(rng) {
      const Va = pick(rng, 50, 150, 25); const Ca = pick(rng, 0.1, 0.4, 0.1); const Vb = pick(rng, 25, 100, 25); let Cb = pick(rng, 0.05, 0.3, 0.05);
      let nA = Va * Ca, nB = Vb * Cb; if (Math.abs(nA - nB) < 1e-9) { Cb = +(Cb + 0.05).toFixed(2); nB = Vb * Cb; }
      const acid = nA > nB; const ex = Math.abs(nA - nB) / (Va + Vb); const pH = acid ? -l10(ex) : 14 + l10(ex);
      return { q: `${Va} mL of ${+Ca.toFixed(2)} M HCl is mixed with ${Vb} mL of ${+Cb.toFixed(2)} M NaOH. Find the pH of the mixture at 25 &deg;C.`, answer: +pH.toFixed(2), tol: 0.02, Va, Ca, Vb, Cb,
        sol: `<p>mmol H<sup>+</sup> = ${(Va * Ca).toFixed(2)}; mmol OH<sup>-</sup> = ${(Vb * Cb).toFixed(2)}. Excess ${acid ? 'H<sup>+</sup>' : 'OH<sup>-</sup>'} = ${Math.abs(nA - nB).toFixed(2)} mmol in ${Va + Vb} mL: ${ex.toExponential(3)} M.</p><p>pH = <b>${pH.toFixed(2)}</b>.</p>` };
    }, verify: (p) => { const a = p.Va * p.Ca, b = p.Vb * p.Cb; const ex = Math.abs(a - b) / (p.Va + p.Vb); return a > b ? -Math.log10(ex) : 14 + Math.log10(ex); } },
  { id: 'ie-g20', type: 'mcq', level: 3, exams: EX[3], sub: 'salt hydrolysis',
    make(rng) {
      const S = [['NH<sub>4</sub>Br', 'acidic'], ['Na<sub>2</sub>CO<sub>3</sub>', 'basic'], ['KCl', 'neutral'], ['AlCl<sub>3</sub>', 'acidic'], ['CH<sub>3</sub>COOK', 'basic'], ['LiNO<sub>3</sub>', 'neutral'], ['NaCN', 'basic'], ['FeCl<sub>3</sub>', 'acidic'], ['Na<sub>2</sub>SO<sub>4</sub>', 'neutral']];
      const r = choose(rng, S); const { options, answer } = shuffleOpts(rng, r[1], ['acidic', 'basic', 'neutral', 'a buffer'].filter((x) => x !== r[1]));
      return { q: `An aqueous solution of ${r[0]} is`, options, answer, r,
        sol: `<p>Identify the parent acid and base. ${r[1] === 'acidic' ? 'The cation comes from a weak base and the anion from a strong acid: the cation hydrolyses and releases H<sup>+</sup>.' : r[1] === 'basic' ? 'The anion comes from a weak acid and the cation from a strong base: the anion hydrolyses and releases OH<sup>-</sup>.' : 'Both ions come from strong acid and strong base, so neither hydrolyses.'}</p><p>The solution is <b>${r[1]}</b>.</p>` };
    }, verify: (p) => p.answer },
  { id: 'ie-g21', type: 'mcq', level: 4, exams: EX[4], sub: 'precipitation',
    make(rng) {
      const Ksp = choose(rng, [1e-10, 1e-8, 1e-6, 2e-9]); const c1 = choose(rng, [0.001, 0.01, 0.0002, 0.1]); const c2 = choose(rng, [0.001, 0.01, 0.0001, 0.1]);
      let Q = (c1 / 2) * (c2 / 2); if (Math.abs(Q / Ksp - 1) < 0.01) Q *= 2;
      const right = Q > Ksp ? 'a precipitate forms' : 'no precipitate forms';
      const { options, answer } = shuffleOpts(rng, right, ['a precipitate forms', 'no precipitate forms', 'the solution is exactly saturated', 'K<sub>sp</sub> changes to match Q'].filter((x) => x !== right));
      return { q: `Equal volumes of ${c1} M solution of A<sup>+</sup> and ${c2} M solution of B<sup>-</sup> are mixed. K<sub>sp</sub> of AB is ${fmt(Ksp, 2)}. What happens?`, options, answer, Ksp, c1, c2, Q,
        sol: `<p>After mixing, each concentration is halved: Q = (${c1 / 2})(${c2 / 2}) = ${fmt(Q, 3)}.</p><p>Q ${Q > Ksp ? '&gt;' : '&lt;'} K<sub>sp</sub> = ${fmt(Ksp, 2)}, so <b>${right}</b>.</p>` };
    }, verify: (p) => p.answer },
  { id: 'ie-g22', type: 'nat', level: 4, exams: EX[4], sub: 'salt hydrolysis',
    make(rng) {
      const pKb = choose(rng, [4.5, 4.74, 5, 5.5, 6]); const c = choose(rng, [0.1, 0.01, 0.2, 0.5]);
      const pH = 7 - 0.5 * (pKb + l10(c)); const ans = +pH.toFixed(2);
      return { q: `Find the pH of a ${c} M solution of the chloride of a weak base (pK<sub>b</sub> of the base = ${pKb}). Take K<sub>w</sub> = 10<sup>-14</sup>.`, answer: ans, tol: 0.03, pKb, c,
        sol: `<p>The cation hydrolyses: pH = 7 - &frac12;(pK<sub>b</sub> + log c) = 7 - &frac12;(${pKb} + (${l10(c).toFixed(3)})) = <b>${ans}</b>.</p>` };
    }, verify: (p) => 7 - 0.5 * (p.pKb + Math.log10(p.c)) },
  { id: 'ie-g23', type: 'nat', level: 4, exams: EX[4], sub: 'salt of weak acid and weak base',
    make(rng) {
      const pKa = pick(rng, 4, 6, 0.25); const pKb = pick(rng, 4, 6, 0.25);
      const ans = 7 + 0.5 * (pKa - pKb);
      return { q: `A salt is formed from a weak acid (pK<sub>a</sub> = ${pKa}) and a weak base (pK<sub>b</sub> = ${pKb}). Find the pH of its aqueous solution. (The concentration of the salt is not needed.)`, answer: +ans.toFixed(3), tol: 0.02, pKa, pKb,
        sol: `<p>pH = 7 + &frac12;(pK<sub>a</sub> - pK<sub>b</sub>) = 7 + &frac12;(${pKa} - ${pKb}) = <b>${ans.toFixed(3)}</b>.</p>` };
    }, verify: (p) => 7 + 0.5 * (p.pKa - p.pKb) },
  { id: 'ie-g24', type: 'nat', level: 4, exams: EX[4], sub: 'degree of hydrolysis',
    make(rng) {
      const pKa = choose(rng, [4, 4.5, 5, 5.5, 6]); const c = choose(rng, [0.1, 0.01, 0.05]); const Kh = 1e-14 / 10 ** -pKa;
      const h = Math.sqrt(Kh / c); const ans = +(h * 100).toPrecision(3);
      return { q: `Find the percentage hydrolysis of the anion in ${c} M sodium salt of a weak acid with pK<sub>a</sub> = ${pKa} (K<sub>w</sub> = 10<sup>-14</sup>).`, answer: ans, tol: ans * 0.02, pKa, c, unit: '%',
        sol: `<p>K<sub>h</sub> = K<sub>w</sub>/K<sub>a</sub> = 10<sup>-${14 - pKa}</sup>. h = &radic;(K<sub>h</sub>/c) = &radic;(${fmt(Kh, 3)}/${c}) = ${fmt(h, 3)}.</p><p>Percentage hydrolysis = <b>${fmt(ans, 3)}%</b>.</p>` };
    }, verify: (p) => 100 * Math.sqrt(1e-14 / 10 ** -p.pKa / p.c) },
];

export default {
  topic: 'ionic-equilibrium',
  groups: {
    ...XGR,
    m1: { title: 'Match the species with its role', list1: ['A. BF<sub>3</sub>', 'B. NH<sub>3</sub>', 'C. Cl<sup>-</sup>', 'D. HCO<sub>3</sub><sup>-</sup>'], list2: ['p. Lewis base that also accepts H<sup>+</sup> readily', 'q. Lewis acid with an incomplete octet', 'r. Conjugate base of a strong acid, with negligible basicity in water', 's. Amphiprotic ion'] },
    m2: { title: 'Match the 0.1 M salt solution with its pH at 25 &deg;C (K<sub>a</sub> of acetic acid and K<sub>b</sub> of ammonia are nearly equal)', list1: ['A. NaCl', 'B. CH<sub>3</sub>COONa', 'C. NH<sub>4</sub>Cl', 'D. CH<sub>3</sub>COONH<sub>4</sub>'], list2: ['p. pH below 7', 'q. pH above 7', 'r. pH close to 7 although both ions hydrolyse', 's. pH exactly 7 because neither ion reacts with water'] },
    m3: { title: 'Match the salt with its solubility product in terms of molar solubility s', list1: ['A. AgCl', 'B. Ag<sub>2</sub>CrO<sub>4</sub>', 'C. Al(OH)<sub>3</sub>', 'D. Ca<sub>3</sub>(PO<sub>4</sub>)<sub>2</sub>'], list2: ['p. K<sub>sp</sub> = s<sup>2</sup>', 'q. K<sub>sp</sub> = 4s<sup>3</sup>', 'r. K<sub>sp</sub> = 27s<sup>4</sup>', 's. K<sub>sp</sub> = 108s<sup>5</sup>'] },
    m4: { title: 'Match the titration with a suitable indicator', list1: ['A. HCl against NaOH', 'B. CH<sub>3</sub>COOH against NaOH', 'C. HCl against NH<sub>3</sub>', 'D. CH<sub>3</sub>COOH against NH<sub>3</sub>'], list2: ['p. Methyl orange', 'q. Phenolphthalein', 'r. Either of these two works', 's. No indicator gives a sharp end point'] },
    p1: { title: 'Titrating acetic acid with sodium hydroxide', passage: '<p>25.0 mL of 0.100 M CH<sub>3</sub>COOH (pK<sub>a</sub> = 4.74) is titrated with 0.100 M NaOH at 25 &deg;C. Volumes are additive. Use log 2 = 0.301.</p>' },
    p2: { title: 'Precipitating magnesium hydroxide', passage: '<p>A solution contains 0.010 M Mg<sup>2+</sup>. The solubility product of Mg(OH)<sub>2</sub> is K<sub>sp</sub> = 1.0 &times; 10<sup>-11</sup> at 25 &deg;C. Sodium hydroxide is added slowly without changing the volume appreciably.</p>' },
    p3: { title: 'Chloride and chromate with silver ions (Mohr method)', passage: '<p>A solution is 0.010 M in Cl<sup>-</sup> and 0.010 M in CrO<sub>4</sub><sup>2-</sup>. Solid AgNO<sub>3</sub> is added slowly, with no change in volume. K<sub>sp</sub>(AgCl) = 1.8 &times; 10<sup>-10</sup>; K<sub>sp</sub>(Ag<sub>2</sub>CrO<sub>4</sub>) = 1.1 &times; 10<sup>-12</sup>.</p>' },
  },
  items: [
    // ---------- Level 1 ----------
    mk('ie-001', 1, 'Arrhenius theory', 'According to Arrhenius, an acid is a substance that', 'gives H<sup>+</sup> ions in aqueous solution', ['accepts a proton from water', 'accepts an electron pair', 'gives OH<sup>-</sup> ions in aqueous solution'], '<p>Arrhenius: acids give H<sup>+</sup> (really H<sub>3</sub>O<sup>+</sup>) in water, bases give OH<sup>-</sup>. Accepting a proton is the Br&oslash;nsted-Lowry idea of a base; accepting an electron pair is the Lewis idea of an acid.</p>'),
    mk('ie-002', 1, 'conjugate pairs', 'The conjugate base of H<sub>2</sub>SO<sub>4</sub> is', 'HSO<sub>4</sub><sup>-</sup>', ['SO<sub>4</sub><sup>2-</sup>', 'H<sub>3</sub>SO<sub>4</sub><sup>+</sup>', 'HSO<sub>3</sub><sup>-</sup>'], '<p>The conjugate base is the acid minus one H<sup>+</sup>: H<sub>2</sub>SO<sub>4</sub> &rarr; HSO<sub>4</sub><sup>-</sup>. SO<sub>4</sub><sup>2-</sup> is the conjugate base of HSO<sub>4</sub><sup>-</sup>, two steps away. H<sub>3</sub>SO<sub>4</sub><sup>+</sup> would be the conjugate <i>acid</i>.</p>'),
    nat('ie-003', 1, 'pH of strong acid', 'Find the pH of 0.01 M HCl at 25 &deg;C.', 2, 0, '', '<p>HCl is a strong acid, fully ionised: [H<sup>+</sup>] = 0.01 = 10<sup>-2</sup> M.</p><p>pH = -log 10<sup>-2</sup> = <b>2</b>.</p>', '', () => -l10(0.01)),
    mk('ie-004', 1, 'Lewis concept', 'Which of these is a Lewis acid?', 'BF<sub>3</sub>', ['NH<sub>3</sub>', 'OH<sup>-</sup>', 'F<sup>-</sup>'], '<p>A Lewis acid accepts an electron pair. Boron in BF<sub>3</sub> has only six electrons and an empty p orbital, so it accepts a pair. NH<sub>3</sub>, OH<sup>-</sup> and F<sup>-</sup> have lone pairs to give: they are Lewis bases.</p>'),
    mk('ie-005', 1, 'ionic product of water', 'The pH of pure water at 25 &deg;C is', '7, because [H<sup>+</sup>] = [OH<sup>-</sup>] = 10<sup>-7</sup> M', ['0, because water is neutral', '14, because K<sub>w</sub> = 10<sup>-14</sup>', '1, because water is a weak electrolyte'], '<p>K<sub>w</sub> = [H<sup>+</sup>][OH<sup>-</sup>] = 10<sup>-14</sup> at 25 &deg;C. In pure water the two are equal, so each is 10<sup>-7</sup> M and pH = 7.</p>', 'The value 7 is for 25 &deg;C only.'),
    mk('ie-006', 1, 'conjugate pairs', 'The conjugate acid of NH<sub>3</sub> is', 'NH<sub>4</sub><sup>+</sup>', ['NH<sub>2</sub><sup>-</sup>', 'NH<sub>2</sub>OH', 'N<sub>2</sub>H<sub>4</sub>'], '<p>The conjugate acid is the base plus one H<sup>+</sup>: NH<sub>3</sub> + H<sup>+</sup> &rarr; NH<sub>4</sub><sup>+</sup>. NH<sub>2</sub><sup>-</sup> is the conjugate <i>base</i> of NH<sub>3</sub>.</p>'),
    mk('ie-007', 1, 'salt hydrolysis', 'A 0.1 M aqueous solution of NaCl at 25 &deg;C has a pH', 'equal to 7', ['less than 7', 'more than 7', 'equal to 1'], '<p>NaCl comes from a strong acid (HCl) and a strong base (NaOH). Neither Na<sup>+</sup> nor Cl<sup>-</sup> reacts with water, so there is no hydrolysis and the solution is neutral.</p>'),
    mk('ie-008', 1, 'buffer solutions', 'A buffer solution is one that', 'resists a change in pH when small amounts of acid or base are added', ['has a pH of exactly 7', 'does not contain any ions', 'cannot change its pH at all, however much acid is added'], '<p>A buffer contains a weak acid and its conjugate base (or a weak base and its conjugate acid). It absorbs small additions of H<sup>+</sup> or OH<sup>-</sup>, so pH changes only slightly. A large addition exhausts it, so option 4 is wrong.</p>'),
    mk('ie-009', 1, 'solubility product', 'The solubility product of PbCl<sub>2</sub> is written as', '[Pb<sup>2+</sup>][Cl<sup>-</sup>]<sup>2</sup>', ['[Pb<sup>2+</sup>][Cl<sup>-</sup>]', '[Pb<sup>2+</sup>]<sup>2</sup>[Cl<sup>-</sup>]', '[PbCl<sub>2</sub>]'], '<p>PbCl<sub>2</sub>(s) &#8652; Pb<sup>2+</sup> + 2Cl<sup>-</sup>. The coefficient becomes the power: K<sub>sp</sub> = [Pb<sup>2+</sup>][Cl<sup>-</sup>]<sup>2</sup>. The solid is left out.</p>'),
    mk('ie-010', 1, 'common ion effect', 'Adding sodium acetate to acetic acid solution', 'decreases the ionisation of acetic acid', ['increases the ionisation of acetic acid', 'does not change the ionisation of acetic acid', 'increases the value of K<sub>a</sub>'], '<p>CH<sub>3</sub>COOH &#8652; H<sup>+</sup> + CH<sub>3</sub>COO<sup>-</sup>. Sodium acetate adds the common ion CH<sub>3</sub>COO<sup>-</sup>; by Le Chatelier the equilibrium shifts left, so less acid ionises and [H<sup>+</sup>] falls. K<sub>a</sub> itself stays the same (it depends only on temperature).</p>'),
    nat('ie-011', 1, 'pH and pOH', 'A solution has pH = 4 at 25 &deg;C. What is its pOH?', 10, 0, '', '<p>pH + pOH = 14 at 25 &deg;C, so pOH = 14 - 4 = <b>10</b>.</p>', '', () => 14 - 4),
    mk('ie-012', 1, 'Br&oslash;nsted-Lowry theory', 'In the reaction NH<sub>3</sub> + H<sub>2</sub>O &#8652; NH<sub>4</sub><sup>+</sup> + OH<sup>-</sup>, water acts as', 'a Br&oslash;nsted acid', ['a Br&oslash;nsted base', 'a Lewis acid', 'a catalyst'], '<p>Water gives a proton to NH<sub>3</sub>, so water is the Br&oslash;nsted acid and NH<sub>3</sub> is the base. The conjugate pairs are NH<sub>4</sub><sup>+</sup>/NH<sub>3</sub> and H<sub>2</sub>O/OH<sup>-</sup>.</p>'),

    // ---------- Level 2 ----------
    nat('ie-013', 2, 'pH of strong base', 'Find the pH of 0.001 M NaOH at 25 &deg;C.', 11, 0, '', '<p>NaOH is a strong base: [OH<sup>-</sup>] = 10<sup>-3</sup> M, so pOH = 3.</p><p>pH = 14 - 3 = <b>11</b>.</p>', 'Do not report the pOH (3) as the pH.', () => 14 + l10(0.001)),
    mk('ie-014', 2, 'amphiprotic species', 'The conjugate acid and the conjugate base of H<sub>2</sub>PO<sub>4</sub><sup>-</sup> are respectively', 'H<sub>3</sub>PO<sub>4</sub> and HPO<sub>4</sub><sup>2-</sup>', ['HPO<sub>4</sub><sup>2-</sup> and H<sub>3</sub>PO<sub>4</sub>', 'H<sub>3</sub>PO<sub>4</sub> and PO<sub>4</sub><sup>3-</sup>', 'H<sub>3</sub>PO<sub>3</sub> and HPO<sub>3</sub><sup>2-</sup>'], '<p>Conjugate acid: add H<sup>+</sup> &rarr; H<sub>3</sub>PO<sub>4</sub>. Conjugate base: remove H<sup>+</sup> &rarr; HPO<sub>4</sub><sup>2-</sup>. Option 2 swaps the two; option 3 skips a step; option 4 is a different acid (phosphorous).</p>'),
    nat('ie-015', 2, 'pH of weak acid', 'Find the pH of 0.10 M acetic acid (K<sub>a</sub> = 1.8 &times; 10<sup>-5</sup>) using [H<sup>+</sup>] = &radic;(K<sub>a</sub>C).', 2.87, 0.02, '', '<p>[H<sup>+</sup>] = &radic;(1.8 &times; 10<sup>-5</sup> &times; 0.10) = &radic;(1.8 &times; 10<sup>-6</sup>) = 1.34 &times; 10<sup>-3</sup> M.</p><p>pH = -log(1.34 &times; 10<sup>-3</sup>) = <b>2.87</b>.</p>', '', () => -l10(Math.sqrt(1.8e-5 * 0.1))),
    nat('ie-016', 2, 'degree of dissociation', 'A 0.10 M solution of a weak monobasic acid has K<sub>a</sub> = 1.0 &times; 10<sup>-5</sup>. Find its percentage ionisation (use &alpha; = &radic;(K<sub>a</sub>/C)).', 1, 0, '%', '<p>&alpha; = &radic;(K<sub>a</sub>/C) = &radic;(10<sup>-5</sup>/0.10) = &radic;(10<sup>-4</sup>) = 0.01.</p><p>Percentage ionisation = 0.01 &times; 100 = <b>1 %</b>.</p>', '', () => Math.sqrt(1e-5 / 0.1) * 100),
    mk('ie-017', 1, 'salt hydrolysis', 'The aqueous solution of NH<sub>4</sub>Cl is', 'acidic, because NH<sub>4</sub><sup>+</sup> donates a proton to water', ['basic, because NH<sub>3</sub> is a base', 'neutral, because it is a salt', 'acidic, because Cl<sup>-</sup> reacts with water'], '<p>NH<sub>4</sub>Cl is the salt of a strong acid and a weak base. NH<sub>4</sub><sup>+</sup> + H<sub>2</sub>O &#8652; NH<sub>3</sub> + H<sub>3</sub>O<sup>+</sup> makes the solution acidic. Cl<sup>-</sup> is the conjugate base of a strong acid and does not react with water.</p>'),
    nat('ie-018', 2, 'Henderson equation', 'A buffer has 0.10 M acetic acid and 0.20 M sodium acetate (pK<sub>a</sub> = 4.74). Find its pH. (log 2 = 0.301)', 5.04, 0.01, '', '<p>Henderson: pH = pK<sub>a</sub> + log([salt]/[acid]) = 4.74 + log(0.20/0.10) = 4.74 + 0.301 = <b>5.04</b>.</p>', 'Put the salt (base) on top; the acid on top gives 4.44.', () => 4.74 + l10(2)),
    nat('ie-019', 2, 'solubility product', 'K<sub>sp</sub> of AgCl is 1.6 &times; 10<sup>-10</sup>. Find its molar solubility in pure water, in units of 10<sup>-5</sup> mol L<sup>-1</sup>.', 1.26, 0.02, '&times; 10<sup>-5</sup> mol L<sup>-1</sup>', '<p>AgCl &#8652; Ag<sup>+</sup> + Cl<sup>-</sup>, so K<sub>sp</sub> = s<sup>2</sup>.</p><p>s = &radic;(1.6 &times; 10<sup>-10</sup>) = 1.26 &times; 10<sup>-5</sup> mol L<sup>-1</sup>. Answer: <b>1.26</b>.</p>', '', () => Math.sqrt(1.6e-10) / 1e-5),
    mk('ie-020', 1, 'salt hydrolysis', 'Which salt gives a basic aqueous solution?', 'Na<sub>2</sub>CO<sub>3</sub>', ['NaCl', 'NH<sub>4</sub>Cl', 'KNO<sub>3</sub>'], '<p>Na<sub>2</sub>CO<sub>3</sub> is the salt of a strong base and the weak acid H<sub>2</sub>CO<sub>3</sub>. CO<sub>3</sub><sup>2-</sup> + H<sub>2</sub>O &#8652; HCO<sub>3</sub><sup>-</sup> + OH<sup>-</sup> gives a basic solution. NaCl and KNO<sub>3</sub> are neutral; NH<sub>4</sub>Cl is acidic.</p>'),
    mk('ie-021', 2, 'precipitation', 'A sparingly soluble salt is precipitated from a solution when', 'the ionic product exceeds the solubility product', ['the ionic product is less than K<sub>sp</sub>', 'the ionic product is zero', 'K<sub>sp</sub> is greater than the ionic product'], '<p>Compare Q (ionic product, with the present concentrations) with K<sub>sp</sub>. If Q &gt; K<sub>sp</sub> the solution is supersaturated and the salt precipitates until Q = K<sub>sp</sub>. If Q &lt; K<sub>sp</sub> the solution is unsaturated.</p>'),
    nat('ie-022', 2, 'polyprotic strong acid', 'Find the pH of 0.05 M H<sub>2</sub>SO<sub>4</sub>, taking both protons as completely ionised.', 1, 0, '', '<p>Each mole gives 2 mol H<sup>+</sup>: [H<sup>+</sup>] = 2 &times; 0.05 = 0.10 M.</p><p>pH = <b>1</b>.</p>', 'Using 0.05 M as [H<sup>+</sup>] gives 1.3.', () => -l10(0.1)),
    mk('ie-023', 2, 'acid strength', 'Four acids have pK<sub>a</sub> values: HA 2.8, HB 4.7, HC 9.2, HD 3.2. Which is the strongest acid?', 'HA', ['HB', 'HC', 'HD'], '<p>A smaller pK<sub>a</sub> means a larger K<sub>a</sub> (K<sub>a</sub> = 10<sup>-pK<sub>a</sub></sup>), so a stronger acid. The smallest pK<sub>a</sub> here is 2.8 (HA).</p>', 'Larger pK<sub>a</sub> means weaker, not stronger.'),
    mk('ie-024', 2, 'ionic product of water', 'On heating pure water from 25 &deg;C to 80 &deg;C, its pH falls below 7. The water is then', 'still neutral, because [H<sup>+</sup>] = [OH<sup>-</sup>]', ['acidic, because pH &lt; 7', 'basic, because K<sub>w</sub> has increased', 'neutral only if pH = 7'], '<p>Ionisation of water is endothermic, so K<sub>w</sub> rises with temperature and [H<sup>+</sup>] = [OH<sup>-</sup>] = &radic;K<sub>w</sub> exceeds 10<sup>-7</sup>. The pH of neutral water falls below 7, yet the water stays neutral because the two ion concentrations stay equal.</p>', 'Neutral means [H<sup>+</sup>] = [OH<sup>-</sup>], not pH = 7.'),
    nat('ie-025', 2, 'dilution of a strong acid', 'A solution of HCl has pH = 2. 10 mL of it is diluted with water to 1000 mL. What is the new pH?', 4, 0, '', '<p>Dilution factor = 1000/10 = 100, so [H<sup>+</sup>] falls from 10<sup>-2</sup> to 10<sup>-4</sup> M.</p><p>pH = <b>4</b>. (Safe, because 10<sup>-4</sup> M is far above the 10<sup>-7</sup> M from water.)</p>', '', () => 2 + l10(100)),
    mk('ie-026', 2, 'indicators', 'In the titration of acetic acid against NaOH, a suitable indicator is', 'phenolphthalein', ['methyl orange', 'methyl red', 'none, because the pH changes too slowly'], '<p>At the equivalence point the solution is sodium acetate, a basic salt (pH about 8.7). Phenolphthalein changes colour at pH 8.3 to 10, which brackets this. Methyl orange (3.1 to 4.4) changes long before the end point.</p>'),
    mk('ie-027', 2, 'Lewis concept', 'Which of the following can act as a Lewis acid but <b>not</b> as a Br&oslash;nsted acid?', 'AlCl<sub>3</sub>', ['H<sub>2</sub>O', 'NH<sub>4</sub><sup>+</sup>', 'HCl'], '<p>AlCl<sub>3</sub> accepts an electron pair (Al has an incomplete octet) but has no proton to give. H<sub>2</sub>O, NH<sub>4</sub><sup>+</sup> and HCl all donate H<sup>+</sup>.</p>'),
    nat('ie-028', 2, 'solubility product', 'The molar solubility of Ca(OH)<sub>2</sub> is 0.01 mol L<sup>-1</sup>. Find K<sub>sp</sub> in units of 10<sup>-6</sup>.', 4, 0, '&times; 10<sup>-6</sup>', '<p>Ca(OH)<sub>2</sub> &#8652; Ca<sup>2+</sup> + 2OH<sup>-</sup>. [Ca<sup>2+</sup>] = s, [OH<sup>-</sup>] = 2s.</p><p>K<sub>sp</sub> = s(2s)<sup>2</sup> = 4s<sup>3</sup> = 4 &times; (0.01)<sup>3</sup> = 4 &times; 10<sup>-6</sup>. Answer: <b>4</b>.</p>', 'Forgetting to square the 2 gives 2 &times; 10<sup>-6</sup>.', () => 4 * 0.01 ** 3 / 1e-6),

    // ---------- Level 3 ----------
    nat('ie-029', 3, 'very dilute solutions', 'Find the pH of 1.0 &times; 10<sup>-8</sup> M HCl at 25 &deg;C, allowing for the H<sup>+</sup> from water.', 6.98, 0.01, '', '<p>Water supplies x, HCl supplies 10<sup>-8</sup>: [H<sup>+</sup>] = 10<sup>-8</sup> + x and [OH<sup>-</sup>] = x. So (10<sup>-8</sup> + x)x = 10<sup>-14</sup>.</p><p>x<sup>2</sup> + 10<sup>-8</sup>x - 10<sup>-14</sup> = 0 gives x = 9.5 &times; 10<sup>-8</sup>.</p><p>[H<sup>+</sup>] = 1.05 &times; 10<sup>-7</sup> M, so pH = <b>6.98</b>.</p>', 'The naive answer 8 is impossible: an acid cannot make the solution basic.', () => -l10((1e-8 + Math.sqrt(1e-16 + 4e-14)) / 2)),
    nat('ie-030', 3, 'Ostwald dilution law', 'A 0.20 M solution of a weak acid HA is 2 % ionised. Find K<sub>a</sub> in units of 10<sup>-5</sup> (take 1 - &alpha; &asymp; 1).', 8, 0, '&times; 10<sup>-5</sup>', '<p>K<sub>a</sub> = C&alpha;<sup>2</sup>/(1 - &alpha;) &asymp; C&alpha;<sup>2</sup> = 0.20 &times; (0.02)<sup>2</sup> = 0.20 &times; 4 &times; 10<sup>-4</sup> = 8 &times; 10<sup>-5</sup>.</p><p>Answer: <b>8</b>.</p>', '&alpha; = 2 % means 0.02, not 2.', () => 0.2 * 0.02 ** 2 / 1e-5),
    mk('ie-031', 3, 'Ostwald dilution law', 'A weak acid is 2 % ionised at a certain concentration. The solution is diluted to one-fourth of its concentration at the same temperature. The new degree of ionisation is about', '4 %', ['1 %', '8 %', '2 %'], '<p>For a weak acid &alpha; = &radic;(K<sub>a</sub>/C). If C becomes C/4, &alpha; becomes &radic;4 = 2 times: 2 % &times; 2 = <b>4 %</b>.</p>', 'Dilution raises &alpha; but lowers [H<sup>+</sup>].'),
    nat('ie-032', 3, 'buffer after adding acid', '1.0 L of a buffer holds 0.20 mol CH<sub>3</sub>COOH and 0.20 mol CH<sub>3</sub>COONa (pK<sub>a</sub> = 4.74). Find the pH after adding 0.050 mol HCl (no volume change).', 4.52, 0.02, '', '<p>HCl turns acetate into acetic acid: CH<sub>3</sub>COO<sup>-</sup> + H<sup>+</sup> &rarr; CH<sub>3</sub>COOH.</p><p>Acid = 0.25 mol, salt = 0.15 mol.</p><p>pH = 4.74 + log(0.15/0.25) = 4.74 + log 0.6 = 4.74 - 0.222 = <b>4.52</b>.</p>', 'Move 0.05 from salt to acid, not only from salt.', () => 4.74 + l10(0.15 / 0.25)),
    nat('ie-033', 3, 'salt hydrolysis', 'Find the pH of 0.10 M sodium acetate (pK<sub>a</sub> of acetic acid = 4.74) at 25 &deg;C using pH = 7 + &frac12;(pK<sub>a</sub> + log C).', 8.87, 0.02, '', '<p>pH = 7 + &frac12;(4.74 + log 0.10) = 7 + &frac12;(4.74 - 1) = 7 + 1.87 = <b>8.87</b>.</p>', 'The salt of a weak acid and strong base must have pH above 7.', () => 7 + 0.5 * (4.74 + l10(0.1))),
    nat('ie-034', 3, 'salt hydrolysis', 'Find the pH of 0.10 M NH<sub>4</sub>Cl (pK<sub>b</sub> of NH<sub>3</sub> = 4.74) using pH = 7 - &frac12;(pK<sub>b</sub> + log C).', 5.13, 0.02, '', '<p>pH = 7 - &frac12;(4.74 + log 0.10) = 7 - &frac12;(3.74) = 7 - 1.87 = <b>5.13</b>.</p>', 'Acidic salt: pH is below 7. Sign of the correction is opposite to a basic salt.', () => 7 - 0.5 * (4.74 + l10(0.1))),
    nat('ie-035', 3, 'salt hydrolysis', 'Find the pH of ammonium cyanide solution (pK<sub>a</sub> of HCN = 9.25, pK<sub>b</sub> of NH<sub>3</sub> = 4.75) using pH = 7 + &frac12;(pK<sub>a</sub> - pK<sub>b</sub>).', 9.25, 0.02, '', '<p>Both ions hydrolyse and pH is independent of concentration: pH = 7 + &frac12;(9.25 - 4.75) = 7 + 2.25 = <b>9.25</b>. The cyanide ion is the stronger base here, so the solution is basic.</p>', '', () => 7 + 0.5 * (9.25 - 4.75)),
    nat('ie-036', 3, 'solubility product', 'The solubility of Ag<sub>2</sub>CrO<sub>4</sub> is 1.0 &times; 10<sup>-4</sup> mol L<sup>-1</sup>. Find its K<sub>sp</sub> in units of 10<sup>-12</sup>.', 4, 0, '&times; 10<sup>-12</sup>', '<p>Ag<sub>2</sub>CrO<sub>4</sub> &#8652; 2Ag<sup>+</sup> + CrO<sub>4</sub><sup>2-</sup>: [Ag<sup>+</sup>] = 2s, [CrO<sub>4</sub><sup>2-</sup>] = s.</p><p>K<sub>sp</sub> = (2s)<sup>2</sup>s = 4s<sup>3</sup> = 4 &times; 10<sup>-12</sup>. Answer: <b>4</b>.</p>', '', () => 4 * 1e-4 ** 3 / 1e-12),
    nat('ie-037', 3, 'common ion effect on solubility', 'K<sub>sp</sub> of AgCl is 1.8 &times; 10<sup>-10</sup>. Find its solubility in 0.10 M NaCl, in units of 10<sup>-9</sup> mol L<sup>-1</sup>.', 1.8, 0.01, '&times; 10<sup>-9</sup> mol L<sup>-1</sup>', '<p>Let solubility = s. [Ag<sup>+</sup>] = s and [Cl<sup>-</sup>] = 0.10 + s &asymp; 0.10.</p><p>s = K<sub>sp</sub>/0.10 = 1.8 &times; 10<sup>-9</sup> mol L<sup>-1</sup>. Answer: <b>1.8</b>. (About 7000 times lower than in pure water, 1.34 &times; 10<sup>-5</sup>.)</p>', '', () => 1.8e-10 / 0.1 / 1e-9),
    nat('ie-038', 3, 'precipitation', 'A solution is 0.010 M in Ag<sup>+</sup>. At what minimum [Cl<sup>-</sup>] does AgCl start to precipitate (K<sub>sp</sub> = 1.8 &times; 10<sup>-10</sup>)? Give the answer in units of 10<sup>-8</sup> M.', 1.8, 0.01, '&times; 10<sup>-8</sup> M', '<p>Precipitation starts when [Ag<sup>+</sup>][Cl<sup>-</sup>] = K<sub>sp</sub>.</p><p>[Cl<sup>-</sup>] = 1.8 &times; 10<sup>-10</sup>/0.010 = 1.8 &times; 10<sup>-8</sup> M. Answer: <b>1.8</b>.</p>', '', () => 1.8e-10 / 0.01 / 1e-8),
    msq('ie-039', 3, 'polyprotic acids', 'For phosphoric acid (K<sub>a1</sub> = 7.5 &times; 10<sup>-3</sup>, K<sub>a2</sub> = 6.2 &times; 10<sup>-8</sup>, K<sub>a3</sub> = 4.8 &times; 10<sup>-13</sup>), choose the correct statements.', ['K<sub>a1</sub> &gt; K<sub>a2</sub> &gt; K<sub>a3</sub> because it is harder to remove a proton from a more negative ion', 'The conjugate base of H<sub>2</sub>PO<sub>4</sub><sup>-</sup> is HPO<sub>4</sub><sup>2-</sup>', 'In 0.1 M H<sub>3</sub>PO<sub>4</sub> almost all the H<sup>+</sup> comes from the first ionisation', 'In 0.1 M H<sub>3</sub>PO<sub>4</sub>, [PO<sub>4</sub><sup>3-</sup>] is about equal to [H<sup>+</sup>]'], [0, 1, 2], '<p>(A) True: removing H<sup>+</sup> from a negative ion is harder. (B) True. (C) True: the ratio K<sub>a1</sub>/K<sub>a2</sub> is about 10<sup>5</sup>, so later steps add very little H<sup>+</sup>. (D) False: [PO<sub>4</sub><sup>3-</sup>] is tiny (about 10<sup>-18</sup> M) next to [H<sup>+</sup>] of about 0.02 M.</p>'),
    mk('ie-040', 3, 'buffer solutions', 'Equal volumes of 0.20 M CH<sub>3</sub>COOH and 0.10 M NaOH are mixed. The pH of the mixture equals', 'pK<sub>a</sub> of acetic acid', ['7', 'pK<sub>a</sub> + log 2', '14 - pK<sub>a</sub>'], '<p>Take 1 L of each: 0.20 mol acid + 0.10 mol NaOH gives 0.10 mol acetate and 0.10 mol acid left (a buffer, half-neutralised). Then pH = pK<sub>a</sub> + log(0.10/0.10) = pK<sub>a</sub>.</p>', 'Do not compare the original 0.20 M and 0.10 M; use the moles after reaction.'),
    nat('ie-041', 3, 'titration curves', 'Find the pH at the equivalence point when 0.10 M acetic acid is titrated with 0.10 M NaOH. The salt solution is 0.050 M and pK<sub>a</sub> = 4.74.', 8.72, 0.02, '', '<p>At equivalence the solution is sodium acetate, 0.050 M (volume doubled).</p><p>pH = 7 + &frac12;(pK<sub>a</sub> + log C) = 7 + &frac12;(4.74 - 1.30) = 7 + 1.72 = <b>8.72</b>.</p>', 'The pH at equivalence is above 7 for a weak acid, not 7.', () => 7 + 0.5 * (4.74 + l10(0.05))),
    nat('ie-042', 3, 'mixing acid and base', '100 mL of 0.10 M HCl is mixed with 100 mL of 0.050 M NaOH. Find the pH.', 1.6, 0.01, '', '<p>Moles H<sup>+</sup> = 0.010, OH<sup>-</sup> = 0.0050. Excess H<sup>+</sup> = 0.0050 mol in 200 mL.</p><p>[H<sup>+</sup>] = 0.0050/0.200 = 0.025 M, so pH = -log 0.025 = <b>1.60</b>.</p>', 'Remember the total volume is 200 mL.', () => -l10(0.005 / 0.2)),
    nat('ie-043', 3, 'ionic product of water', 'At 50 &deg;C, K<sub>w</sub> = 5.5 &times; 10<sup>-14</sup>. Find the pH of neutral water at this temperature.', 6.63, 0.01, '', '<p>Neutral: [H<sup>+</sup>] = &radic;K<sub>w</sub>, so pH = &frac12;pK<sub>w</sub> = &frac12;(13.26) = <b>6.63</b>.</p><p>(pK<sub>w</sub> = -log 5.5 &times; 10<sup>-14</sup> = 14 - 0.74 = 13.26.)</p>', '', () => -0.5 * l10(5.5e-14)),
    mk('ie-044', 3, 'buffer capacity', 'The buffer capacity of an acetic acid / sodium acetate buffer is the highest when', '[CH<sub>3</sub>COOH] = [CH<sub>3</sub>COO<sup>-</sup>] and both are large', ['the solution is exactly neutral', '[CH<sub>3</sub>COO<sup>-</sup>] is ten times [CH<sub>3</sub>COOH]', 'only acetic acid is present'], '<p>Buffer capacity is the amount of strong acid or base absorbed per unit change in pH. It is greatest when acid and base reservoirs are equal (pH = pK<sub>a</sub>) and their concentrations are large. A 10:1 ratio gives lower capacity; pure acid is not a buffer.</p>'),
    mk('ie-045', 3, 'solubility and common ion', 'Silver chloride has the lowest solubility in', '0.1 M CaCl<sub>2</sub>', ['pure water', '0.1 M NaCl', '0.1 M AgNO<sub>3</sub>'], '<p>Solubility s = K<sub>sp</sub>/[common ion]. In 0.1 M NaCl, [Cl<sup>-</sup>] = 0.1. In 0.1 M AgNO<sub>3</sub>, [Ag<sup>+</sup>] = 0.1. In 0.1 M CaCl<sub>2</sub>, [Cl<sup>-</sup>] = 0.2, so s is the smallest, K<sub>sp</sub>/0.2.</p>', 'CaCl<sub>2</sub> gives two Cl<sup>-</sup> per formula unit.'),
    mk('ie-046', 3, 'salt hydrolysis', 'Equimolar solutions of NaCN, CH<sub>3</sub>COONa, NH<sub>4</sub>Cl and NaCl are compared. The pH order is', 'NaCN &gt; CH<sub>3</sub>COONa &gt; NaCl &gt; NH<sub>4</sub>Cl', ['NaCl &gt; NaCN &gt; CH<sub>3</sub>COONa &gt; NH<sub>4</sub>Cl', 'CH<sub>3</sub>COONa &gt; NaCN &gt; NaCl &gt; NH<sub>4</sub>Cl', 'NH<sub>4</sub>Cl &gt; NaCl &gt; CH<sub>3</sub>COONa &gt; NaCN'], '<p>HCN (pK<sub>a</sub> 9.2) is weaker than acetic acid (4.74), so CN<sup>-</sup> is a stronger base than acetate: NaCN has the highest pH. NaCl is neutral. NH<sub>4</sub>Cl is acidic, so it is lowest.</p>'),
    asr('ie-047', 2, 'ionic product of water', 'Pure water is neutral at every temperature.', '[H<sup>+</sup>] = [OH<sup>-</sup>] in pure water at all temperatures.', 0, '<p>Water ionises as H<sub>2</sub>O &#8652; H<sup>+</sup> + OH<sup>-</sup>, producing equal numbers of H<sup>+</sup> and OH<sup>-</sup>. Neutral means exactly this, even when K<sub>w</sub> and the pH change with temperature. Both true, and R explains A.</p>'),
    asr('ie-048', 3, 'very dilute solutions', 'The pH of 10<sup>-8</sup> M HCl at 25 &deg;C is 8.', 'HCl is a strong acid and is completely ionised in water.', 3, '<p>A is false: a solution of an acid cannot have pH above 7. The H<sup>+</sup> from water (about 10<sup>-7</sup> M) cannot be ignored, giving pH about 6.98. R is a true statement but does not rescue the answer 8.</p>', 'Ignoring water gives the impossible pH 8.'),
    asr('ie-049', 3, 'common ion effect', 'The solubility of AgCl decreases when NaCl is added to its saturated solution.', 'The solubility product of AgCl decreases on adding NaCl.', 2, '<p>A is true: Cl<sup>-</sup> is a common ion and pushes AgCl(s) &#8652; Ag<sup>+</sup> + Cl<sup>-</sup> to the left. R is false: K<sub>sp</sub> changes only with temperature; it is the solubility that falls.</p>', 'Ksp is constant at constant temperature.'),
    asr('ie-050', 2, 'common ion effect', 'Acetic acid is less ionised in the presence of sodium acetate.', 'Sodium acetate supplies CH<sub>3</sub>COO<sup>-</sup>, which shifts CH<sub>3</sub>COOH &#8652; H<sup>+</sup> + CH<sub>3</sub>COO<sup>-</sup> to the left.', 0, '<p>Both statements are true and R is the reason: the extra acetate ion suppresses ionisation (common ion effect), lowering [H<sup>+</sup>].</p>'),
    asr('ie-051', 2, 'pH', 'The pH of 0.1 M HCl at 25 &deg;C is 1.', 'K<sub>w</sub> of water is 10<sup>-14</sup> at 25 &deg;C.', 1, '<p>A is true: [H<sup>+</sup>] = 0.1 M, pH = 1. R is also a true fact, but pH of a strong acid comes from its concentration, not from K<sub>w</sub>. So R is not the explanation.</p>'),
    asr('ie-052', 2, 'conjugate pairs', 'The conjugate base of a strong acid is a strong base.', 'A strong acid has a high tendency to donate protons.', 3, '<p>A is false: the stronger the acid, the weaker its conjugate base (Cl<sup>-</sup>, ClO<sub>4</sub><sup>-</sup> are extremely weak bases). R is true on its own.</p>', 'Inverse relation: K<sub>a</sub> &times; K<sub>b</sub> = K<sub>w</sub>.'),
    asr('ie-053', 3, 'Lewis concept', 'Anhydrous AlCl<sub>3</sub> is a Lewis acid.', 'The aluminium atom in AlCl<sub>3</sub> has a complete octet.', 2, '<p>A is true: Al in AlCl<sub>3</sub> has only six electrons around it and accepts a pair (it dimerises to Al<sub>2</sub>Cl<sub>6</sub>). R is false, and that is exactly why A is true.</p>'),
    asr('ie-054', 3, 'Ostwald dilution law', 'On dilution the degree of ionisation of a weak acid increases.', '[H<sup>+</sup>] of the solution also increases on dilution.', 2, '<p>A is true: &alpha; = &radic;(K<sub>a</sub>/C) rises when C falls. R is false: [H<sup>+</sup>] = C&alpha; = &radic;(K<sub>a</sub>C), which decreases on dilution.</p>', 'Fraction ionised up, concentration of ions down.'),
    stm('ie-055', 3, 'pH calculations', 'The pH of 0.0010 M Ba(OH)<sub>2</sub> at 25 &deg;C is 11.3.', 'The pH of 0.010 M acetic acid (K<sub>a</sub> = 1.8 &times; 10<sup>-5</sup>) is 2.', 1, '<p>I: [OH<sup>-</sup>] = 2 &times; 0.0010 = 2 &times; 10<sup>-3</sup>, pOH = 2.70, pH = 11.30. Correct.</p><p>II: [H<sup>+</sup>] = &radic;(1.8 &times; 10<sup>-5</sup> &times; 0.010) = 4.2 &times; 10<sup>-4</sup>, pH = 3.37, not 2. Incorrect (2 would need a strong acid).</p>'),
    stm('ie-056', 3, 'salt hydrolysis', 'The hydrolysis constant K<sub>h</sub> of a salt depends on the concentration of the salt.', 'The degree of hydrolysis of a salt depends on its concentration.', 2, '<p>I is incorrect: K<sub>h</sub> = K<sub>w</sub>/K<sub>a</sub> (or K<sub>w</sub>/K<sub>b</sub>) is constant at a given temperature.</p><p>II is correct: h = &radic;(K<sub>h</sub>/C), so h increases on dilution.</p>'),
    stm('ie-057', 3, 'buffer solutions', 'Diluting a buffer with a little water changes its pH very little.', 'Diluting a buffer with water does not change its buffer capacity.', 1, '<p>I: pH depends on the ratio [salt]/[acid], which does not change on dilution, so the pH is nearly constant. Correct.</p><p>II: capacity depends on the actual amounts of acid and base per litre, which fall on dilution. Incorrect.</p>'),
    stm('ie-058', 3, 'solubility product', 'A salt with a larger K<sub>sp</sub> always has a larger molar solubility than a salt with a smaller K<sub>sp</sub>.', 'For salts of the same type (for example both AB), a larger K<sub>sp</sub> means a larger solubility.', 2, '<p>I is incorrect: solubility links to K<sub>sp</sub> differently for different types. For AgCl, s = &radic;K<sub>sp</sub>; for Ag<sub>2</sub>CrO<sub>4</sub>, s = (K<sub>sp</sub>/4)<sup>1/3</sup>. Ag<sub>2</sub>CrO<sub>4</sub> has the smaller K<sub>sp</sub> (1.1 &times; 10<sup>-12</sup>) but the larger solubility (6.5 &times; 10<sup>-5</sup> against 1.3 &times; 10<sup>-5</sup> M).</p><p>II is correct.</p>', 'Compare K<sub>sp</sub> directly only for the same stoichiometric type.'),
    stm('ie-059', 2, 'conjugate pairs', 'H<sub>2</sub>PO<sub>4</sub><sup>-</sup> is the conjugate base of H<sub>3</sub>PO<sub>4</sub>.', 'H<sub>2</sub>PO<sub>4</sub><sup>-</sup> is an amphiprotic species.', 0, '<p>I: H<sub>3</sub>PO<sub>4</sub> minus H<sup>+</sup> gives H<sub>2</sub>PO<sub>4</sub><sup>-</sup>. Correct.</p><p>II: H<sub>2</sub>PO<sub>4</sub><sup>-</sup> can lose H<sup>+</sup> (to HPO<sub>4</sub><sup>2-</sup>) or gain it (to H<sub>3</sub>PO<sub>4</sub>). Correct.</p>'),
    stm('ie-060', 2, 'ionic product of water', 'Water at 80 &deg;C is neutral.', 'The pH of neutral water is 7 at every temperature.', 1, '<p>I is correct: [H<sup>+</sup>] = [OH<sup>-</sup>].</p><p>II is incorrect: pH of neutral water is 7 only at 25 &deg;C and falls as K<sub>w</sub> rises (about 6.3 at 80 &deg;C).</p>'),
    asr('ie-061', 3, 'salt hydrolysis', 'An aqueous solution of AlCl<sub>3</sub> is acidic.', 'The [Al(H<sub>2</sub>O)<sub>6</sub>]<sup>3+</sup> ion releases protons to water.', 0, '<p>Al<sup>3+</sup> is small and highly charged, polarising the O-H bonds of the coordinated water so that it acts as a proton donor: [Al(H<sub>2</sub>O)<sub>6</sub>]<sup>3+</sup> + H<sub>2</sub>O &#8652; [Al(H<sub>2</sub>O)<sub>5</sub>OH]<sup>2+</sup> + H<sub>3</sub>O<sup>+</sup>. Hence A and R are both true and R is the explanation.</p>'),
    mat('ie-062', 2, 'Lewis and Br&oslash;nsted roles', 'm1', 'Match the species with its role.', 'A-q, B-p, C-r, D-s', ['A-p, B-q, C-s, D-r', 'A-q, B-s, C-r, D-p', 'A-r, B-p, C-q, D-s'], '<p>A. BF<sub>3</sub> has an incomplete octet: Lewis acid (q). B. NH<sub>3</sub> has a lone pair and takes H<sup>+</sup> easily (p). C. Cl<sup>-</sup> is conjugate base of the strong acid HCl (r). D. HCO<sub>3</sub><sup>-</sup> can give or take a proton (s).</p>'),
    mat('ie-063', 3, 'salt hydrolysis', 'm2', 'Match each salt with the pH of its 0.1 M solution.', 'A-s, B-q, C-p, D-r', ['A-s, B-p, C-q, D-r', 'A-r, B-q, C-p, D-s', 'A-q, B-s, C-p, D-r'], '<p>A. NaCl: strong acid + strong base, pH = 7 (s). B. CH<sub>3</sub>COONa: strong base + weak acid, pH &gt; 7 (q). C. NH<sub>4</sub>Cl: weak base + strong acid, pH &lt; 7 (p). D. CH<sub>3</sub>COONH<sub>4</sub>: weak acid + weak base with K<sub>a</sub> &asymp; K<sub>b</sub>, pH about 7 even though both ions hydrolyse (r).</p>', 'Neutral by cancelling hydrolysis (D) differs from neutral by no hydrolysis (A).'),
    mat('ie-064', 3, 'solubility product', 'm3', 'Match each salt with K<sub>sp</sub> in terms of s.', 'A-p, B-q, C-r, D-s', ['A-p, B-r, C-q, D-s', 'A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r'], '<p>A. AgCl: s &times; s = s<sup>2</sup>. B. Ag<sub>2</sub>CrO<sub>4</sub>: (2s)<sup>2</sup>s = 4s<sup>3</sup>. C. Al(OH)<sub>3</sub>: s(3s)<sup>3</sup> = 27s<sup>4</sup>. D. Ca<sub>3</sub>(PO<sub>4</sub>)<sub>2</sub>: (3s)<sup>3</sup>(2s)<sup>2</sup> = 27 &times; 4 s<sup>5</sup> = 108s<sup>5</sup>.</p>'),
    mat('ie-065', 3, 'indicators', 'm4', 'Match each titration with a suitable indicator.', 'A-r, B-q, C-p, D-s', ['A-p, B-q, C-r, D-s', 'A-r, B-p, C-q, D-s', 'A-r, B-q, C-s, D-p'], '<p>A. Strong acid with strong base: sharp change over pH 3 to 11, so either indicator works (r). B. Weak acid with strong base: equivalence pH above 7, phenolphthalein (q). C. Strong acid with weak base: equivalence pH below 7, methyl orange (p). D. Weak acid with weak base: no sharp jump, no indicator is suitable (s).</p>'),
    msq('ie-066', 2, 'Lewis concept', 'Which of the following are Lewis acids?', ['BF<sub>3</sub>', 'AlCl<sub>3</sub>', 'NH<sub>3</sub>', 'Fe<sup>3+</sup>'], [0, 1, 3], '<p>BF<sub>3</sub> and AlCl<sub>3</sub> have incomplete octets; Fe<sup>3+</sup> is a metal cation with empty orbitals that accepts lone pairs. NH<sub>3</sub> has a lone pair to donate: it is a Lewis base.</p>'),
    msq('ie-067', 2, 'amphiprotic species', 'Which of the following are amphiprotic (can both donate and accept a proton)?', ['H<sub>2</sub>O', 'HCO<sub>3</sub><sup>-</sup>', 'H<sub>2</sub>PO<sub>4</sub><sup>-</sup>', 'NH<sub>4</sub><sup>+</sup>', 'CO<sub>3</sub><sup>2-</sup>'], [0, 1, 2], '<p>H<sub>2</sub>O (to H<sub>3</sub>O<sup>+</sup> or OH<sup>-</sup>), HCO<sub>3</sub><sup>-</sup> (to H<sub>2</sub>CO<sub>3</sub> or CO<sub>3</sub><sup>2-</sup>) and H<sub>2</sub>PO<sub>4</sub><sup>-</sup> do both. NH<sub>4</sub><sup>+</sup> can only donate; CO<sub>3</sub><sup>2-</sup> can only accept.</p>'),
    msq('ie-068', 2, 'salt hydrolysis', 'Which of these 0.1 M solutions are acidic (pH &lt; 7) at 25 &deg;C?', ['NH<sub>4</sub>Cl', 'FeCl<sub>3</sub>', 'CH<sub>3</sub>COONa', 'ZnSO<sub>4</sub>', 'K<sub>2</sub>SO<sub>4</sub>'], [0, 1, 3], '<p>NH<sub>4</sub>Cl, FeCl<sub>3</sub> and ZnSO<sub>4</sub> contain cations of weak bases (NH<sub>3</sub>, Fe(OH)<sub>3</sub>, Zn(OH)<sub>2</sub>) with anions of strong acids, so the cations hydrolyse and give H<sup>+</sup>. CH<sub>3</sub>COONa is basic; K<sub>2</sub>SO<sub>4</sub> is neutral.</p>'),
    msq('ie-069', 3, 'common ion effect', 'Which additions to 0.1 M acetic acid <b>decrease</b> its degree of ionisation?', ['Solid CH<sub>3</sub>COONa', 'HCl', 'Water', 'NaOH'], [0, 1], '<p>Sodium acetate and HCl both add a product ion (CH<sub>3</sub>COO<sup>-</sup>, H<sup>+</sup>): common ion effect pushes the equilibrium left. Water (dilution) increases &alpha;. NaOH removes H<sup>+</sup>, pulling the equilibrium right.</p>'),
    msq('ie-070', 3, 'buffer solutions', 'Which of these mixtures (each in water) form a buffer?', ['0.1 mol HCl + 0.1 mol NaCl', '0.2 mol CH<sub>3</sub>COOH + 0.1 mol NaOH', '0.1 mol NH<sub>3</sub> + 0.2 mol HCl', '0.1 mol NaH<sub>2</sub>PO<sub>4</sub> + 0.1 mol Na<sub>2</sub>HPO<sub>4</sub>'], [1, 3], '<p>(A) Strong acid with its salt: no buffer. (B) 0.1 mol CH<sub>3</sub>COOH and 0.1 mol CH<sub>3</sub>COONa remain: buffer. (C) 0.1 mol NH<sub>4</sub>Cl and 0.1 mol excess HCl: strong acid dominates, no buffer. (D) Conjugate acid-base pair H<sub>2</sub>PO<sub>4</sub><sup>-</sup>/HPO<sub>4</sub><sup>2-</sup>: buffer.</p>'),
    msq('ie-071', 3, 'precipitation', 'Which statements about precipitation of a sparingly soluble salt are correct?', ['It begins when the ionic product exceeds K<sub>sp</sub>', 'A common ion lowers the salt&rsquo;s solubility', 'K<sub>sp</sub> changes with temperature', 'A larger K<sub>sp</sub> always means a larger solubility'], [0, 1, 2], '<p>A, B and C are correct. D is false: the link between K<sub>sp</sub> and solubility depends on the type of salt (AB, AB<sub>2</sub>, A<sub>2</sub>B and so on).</p>'),

    // ---------- Level 4 ----------
    nat('ie-072', 4, 'strong and weak acid mixtures', '100 mL of 0.10 M HCl is mixed with 100 mL of 0.10 M acetic acid (K<sub>a</sub> = 1.8 &times; 10<sup>-5</sup>). Find the pH.', 1.3, 0.01, '', '<p>After mixing, HCl = 0.050 M and CH<sub>3</sub>COOH = 0.050 M. HCl gives [H<sup>+</sup>] = 0.050.</p><p>Acetic acid is suppressed by this H<sup>+</sup>: [CH<sub>3</sub>COO<sup>-</sup>] = K<sub>a</sub> &times; 0.050/0.050 = 1.8 &times; 10<sup>-5</sup>, negligible. So [H<sup>+</sup>] = 0.050 and pH = <b>1.30</b>.</p>', 'Do not add &radic;(K<sub>a</sub>C) from the weak acid separately.', () => -l10(0.05)),
    nat('ie-073', 4, 'pH of weak acid (quadratic)', 'Find the pH of 1.0 &times; 10<sup>-3</sup> M acetic acid (K<sub>a</sub> = 1.8 &times; 10<sup>-5</sup>) <b>without</b> assuming &alpha; is small.', 3.9, 0.01, '', '<p>x<sup>2</sup>/(0.001 - x) = 1.8 &times; 10<sup>-5</sup> gives x<sup>2</sup> + 1.8 &times; 10<sup>-5</sup>x - 1.8 &times; 10<sup>-8</sup> = 0.</p><p>x = [-1.8 &times; 10<sup>-5</sup> + &radic;(3.24 &times; 10<sup>-10</sup> + 7.2 &times; 10<sup>-8</sup>)]/2 = 1.25 &times; 10<sup>-4</sup> M.</p><p>pH = <b>3.90</b>. (The shortcut &radic;(K<sub>a</sub>C) gives 3.87, as &alpha; is about 12 %, too large for the approximation.)</p>', '', () => -l10((-1.8e-5 + Math.sqrt(1.8e-5 ** 2 + 4 * 1.8e-8)) / 2)),
    nat('ie-074', 4, 'polyprotic acids', 'Find [S<sup>2-</sup>] in a solution saturated with H<sub>2</sub>S (0.10 M) and 0.20 M in HCl. K<sub>a1</sub> = 1 &times; 10<sup>-7</sup>, K<sub>a2</sub> = 1 &times; 10<sup>-14</sup>. Give the answer in units of 10<sup>-21</sup> M.', 2.5, 0.05, '&times; 10<sup>-21</sup> M', '<p>Overall: H<sub>2</sub>S &#8652; 2H<sup>+</sup> + S<sup>2-</sup>, K = K<sub>a1</sub>K<sub>a2</sub> = 10<sup>-21</sup>.</p><p>[S<sup>2-</sup>] = K[H<sub>2</sub>S]/[H<sup>+</sup>]<sup>2</sup> = 10<sup>-21</sup> &times; 0.10/(0.20)<sup>2</sup> = 10<sup>-22</sup>/0.04 = 2.5 &times; 10<sup>-21</sup> M. Answer: <b>2.5</b>.</p>', 'Without HCl, [S<sup>2-</sup>] would equal K<sub>a2</sub> = 10<sup>-14</sup>. Acid suppresses it enormously.', () => 1e-21 * 0.1 / 0.04 / 1e-21),
    nat('ie-075', 4, 'selective precipitation', 'A solution is 0.010 M in Cl<sup>-</sup> and 0.010 M in I<sup>-</sup>. Solid AgNO<sub>3</sub> is added until AgCl just begins to precipitate (K<sub>sp</sub>: AgCl 2 &times; 10<sup>-10</sup>, AgI 1 &times; 10<sup>-16</sup>). Find [I<sup>-</sup>] left, in units of 10<sup>-9</sup> M.', 5, 0, '&times; 10<sup>-9</sup> M', '<p>AgI needs far less Ag<sup>+</sup>, so it precipitates first. AgCl begins when [Ag<sup>+</sup>] = 2 &times; 10<sup>-10</sup>/0.010 = 2 &times; 10<sup>-8</sup> M.</p><p>[I<sup>-</sup>] = 1 &times; 10<sup>-16</sup>/(2 &times; 10<sup>-8</sup>) = 5 &times; 10<sup>-9</sup> M. Answer: <b>5</b> (only 5 &times; 10<sup>-5</sup> % of the iodide remains: nearly perfect separation).</p>', '', () => 1e-16 / (2e-10 / 0.01) / 1e-9),
    nat('ie-076', 4, 'precipitation and pH', 'At what pH does Mg(OH)<sub>2</sub> (K<sub>sp</sub> = 1.0 &times; 10<sup>-11</sup>) just begin to precipitate from 0.010 M Mg<sup>2+</sup>?', 9.5, 0.01, '', '<p>[OH<sup>-</sup>]<sup>2</sup> = K<sub>sp</sub>/[Mg<sup>2+</sup>] = 10<sup>-11</sup>/10<sup>-2</sup> = 10<sup>-9</sup>, so [OH<sup>-</sup>] = 3.16 &times; 10<sup>-5</sup> M.</p><p>pOH = 4.50, pH = <b>9.50</b>.</p>', '', () => 14 + l10(Math.sqrt(1e-11 / 0.01))),
    nat('ie-077', 4, 'solubility and pH', 'Find the solubility of Mg(OH)<sub>2</sub> (K<sub>sp</sub> = 1.0 &times; 10<sup>-11</sup>) in a buffer of pH 10, in units of 10<sup>-3</sup> mol L<sup>-1</sup>.', 1, 0, '&times; 10<sup>-3</sup> mol L<sup>-1</sup>', '<p>pH 10 means [OH<sup>-</sup>] = 10<sup>-4</sup> M (fixed by the buffer).</p><p>s = [Mg<sup>2+</sup>] = K<sub>sp</sub>/[OH<sup>-</sup>]<sup>2</sup> = 10<sup>-11</sup>/10<sup>-8</sup> = 10<sup>-3</sup> mol L<sup>-1</sup>. Answer: <b>1</b>.</p>', 'The buffer fixes [OH<sup>-</sup>]; do not use K<sub>sp</sub> = 4s<sup>3</sup> here.', () => 1e-11 / 1e-8 / 1e-3),
    nat('ie-078', 4, 'basic buffer', '100 mL of 0.20 M NH<sub>3</sub> is mixed with 100 mL of 0.10 M NH<sub>4</sub>Cl (pK<sub>b</sub> of NH<sub>3</sub> = 4.74). Find the pH of the mixture. (log 2 = 0.301)', 9.56, 0.02, '', '<p>After mixing: [NH<sub>3</sub>] = 0.10 M, [NH<sub>4</sub><sup>+</sup>] = 0.050 M.</p><p>pOH = pK<sub>b</sub> + log([salt]/[base]) = 4.74 + log 0.5 = 4.74 - 0.301 = 4.44.</p><p>pH = 14 - 4.44 = <b>9.56</b>.</p>', 'Use pOH for a basic buffer, then convert.', () => 14 - (4.74 + l10(0.5))),
    nat('ie-079', 4, 'degree of hydrolysis', 'Find the degree of hydrolysis of 0.10 M sodium acetate (K<sub>a</sub> = 1.8 &times; 10<sup>-5</sup>), in units of 10<sup>-5</sup>.', 7.45, 0.1, '&times; 10<sup>-5</sup>', '<p>K<sub>h</sub> = K<sub>w</sub>/K<sub>a</sub> = 10<sup>-14</sup>/1.8 &times; 10<sup>-5</sup> = 5.56 &times; 10<sup>-10</sup>.</p><p>h = &radic;(K<sub>h</sub>/C) = &radic;(5.56 &times; 10<sup>-9</sup>) = 7.45 &times; 10<sup>-5</sup>. Answer: <b>7.45</b>.</p>', '', () => Math.sqrt(1e-14 / 1.8e-5 / 0.1) / 1e-5),
    nat('ie-080', 4, 'polyprotic acids (quadratic)', 'Find the pH of 0.10 M H<sub>3</sub>PO<sub>4</sub> using K<sub>a1</sub> = 7.5 &times; 10<sup>-3</sup> only, solving the quadratic exactly.', 1.62, 0.01, '', '<p>x<sup>2</sup>/(0.10 - x) = 7.5 &times; 10<sup>-3</sup> gives x<sup>2</sup> + 7.5 &times; 10<sup>-3</sup>x - 7.5 &times; 10<sup>-4</sup> = 0.</p><p>x = [-7.5 &times; 10<sup>-3</sup> + &radic;(5.6 &times; 10<sup>-5</sup> + 3 &times; 10<sup>-3</sup>)]/2 = 0.0239 M.</p><p>pH = <b>1.62</b>. The shortcut &radic;(K<sub>a</sub>C) = 0.027 (pH 1.57) is poor since &alpha; is 24 %.</p>', 'The approximation fails when &alpha; is above about 5 %.', () => -l10((-7.5e-3 + Math.sqrt(7.5e-3 ** 2 + 4 * 7.5e-4)) / 2)),
    nat('ie-081', 4, 'temperature and K<sub>w</sub> (mixed with thermodynamics)', 'K<sub>w</sub> is 1.0 &times; 10<sup>-14</sup> at 298 K and 1.0 &times; 10<sup>-13</sup> at 333 K. Find &Delta;H of ionisation of water in kJ mol<sup>-1</sup> (R = 8.314 J K<sup>-1</sup> mol<sup>-1</sup>).', 54.3, 0.5, 'kJ mol<sup>-1</sup>', '<p>van&rsquo;t Hoff: ln(K<sub>2</sub>/K<sub>1</sub>) = (&Delta;H/R)(1/T<sub>1</sub> - 1/T<sub>2</sub>).</p><p>ln 10 = 2.303; 1/298 - 1/333 = 3.527 &times; 10<sup>-4</sup> K<sup>-1</sup>.</p><p>&Delta;H = 8.314 &times; 2.303/3.527 &times; 10<sup>-4</sup> = 5.43 &times; 10<sup>4</sup> J = <b>54.3 kJ mol<sup>-1</sup></b>. Positive: ionisation of water is endothermic.</p>', '', () => 8.314 * Math.log(10) / (1 / 298 - 1 / 333) / 1000),
    mk('ie-082', 4, 'titration curves', 'In the titration of 0.1 M NH<sub>3</sub> with 0.1 M HCl, the pH at exactly half-way to the equivalence point (pK<sub>b</sub> of NH<sub>3</sub> = 4.74) is', '9.26', ['4.74', '7.00', '5.13'], '<p>At the half-way point [NH<sub>3</sub>] = [NH<sub>4</sub><sup>+</sup>], so pOH = pK<sub>b</sub> = 4.74 and pH = 14 - 4.74 = <b>9.26</b>. (5.13 is the pH at the equivalence point of a 0.1 M ammonium chloride solution; 4.74 is the pOH.)</p>', 'The half-way point of a base titration has pOH = pK<sub>b</sub>, not pH = pK<sub>b</sub>.'),
    mk('ie-083', 4, 'salt hydrolysis', 'Four 0.1 M solutions are compared: HCl, NaHSO<sub>4</sub> (K<sub>a</sub> of HSO<sub>4</sub><sup>-</sup> = 1.2 &times; 10<sup>-2</sup>), CH<sub>3</sub>COOH (K<sub>a</sub> = 1.8 &times; 10<sup>-5</sup>) and NH<sub>4</sub>Cl (K<sub>b</sub> of NH<sub>3</sub> = 1.8 &times; 10<sup>-5</sup>). The order of increasing pH is', 'HCl &lt; NaHSO<sub>4</sub> &lt; CH<sub>3</sub>COOH &lt; NH<sub>4</sub>Cl', ['HCl &lt; CH<sub>3</sub>COOH &lt; NaHSO<sub>4</sub> &lt; NH<sub>4</sub>Cl', 'NaHSO<sub>4</sub> &lt; HCl &lt; NH<sub>4</sub>Cl &lt; CH<sub>3</sub>COOH', 'HCl &lt; NaHSO<sub>4</sub> &lt; NH<sub>4</sub>Cl &lt; CH<sub>3</sub>COOH'], '<p>HCl: pH 1.0. NaHSO<sub>4</sub>: HSO<sub>4</sub><sup>-</sup> is a fairly strong acid; solving x<sup>2</sup>/(0.1 - x) = 0.012 gives x = 0.029 M and pH 1.53. CH<sub>3</sub>COOH: pH 2.87. NH<sub>4</sub>Cl: K<sub>a</sub> of NH<sub>4</sub><sup>+</sup> = 5.6 &times; 10<sup>-10</sup>, giving pH 5.13. So the order is HCl &lt; NaHSO<sub>4</sub> &lt; CH<sub>3</sub>COOH &lt; NH<sub>4</sub>Cl.</p>', 'NaHSO<sub>4</sub> is an acidic salt much stronger than acetic acid, since HSO<sub>4</sub><sup>-</sup> is a strong-ish acid.'),
    msq('ie-084', 4, 'ionic product of water', 'Pure water is heated from 25 &deg;C to 80 &deg;C. Which statements are correct?', ['K<sub>w</sub> increases', 'pH of the water decreases', 'The water becomes acidic', '[H<sup>+</sup>] remains equal to [OH<sup>-</sup>]'], [0, 1, 3], '<p>Ionisation is endothermic, so K<sub>w</sub> rises; [H<sup>+</sup>] = &radic;K<sub>w</sub> rises, so the pH falls. Since [H<sup>+</sup>] = [OH<sup>-</sup>] still, the water is neutral, not acidic.</p>'),
    msq('ie-085', 4, 'amphoteric substances', 'Which of the following statements about Al(OH)<sub>3</sub> are correct?', ['It dissolves in excess NaOH to form [Al(OH)<sub>4</sub>]<sup>-</sup>', 'It dissolves in dilute HCl', 'It acts as a Lewis acid when it dissolves in NaOH', 'It is a strong base like NaOH'], [0, 1, 2], '<p>Al(OH)<sub>3</sub> is amphoteric: with acid it acts as a base (Al(OH)<sub>3</sub> + 3H<sup>+</sup> &rarr; Al<sup>3+</sup> + 3H<sub>2</sub>O) and with excess OH<sup>-</sup> it accepts OH<sup>-</sup> (a Lewis acid) to form [Al(OH)<sub>4</sub>]<sup>-</sup>. It is a weak, sparingly soluble base, not strong.</p>'),
    stm('ie-086', 4, 'mixed', 'Mixing of 0.1 M NH<sub>3</sub> with NH<sub>4</sub>Cl lowers the pH of the NH<sub>3</sub> solution.', 'The effect in Statement I is the common ion effect on the ionisation NH<sub>3</sub> + H<sub>2</sub>O &#8652; NH<sub>4</sub><sup>+</sup> + OH<sup>-</sup>.', 0, '<p>Added NH<sub>4</sub><sup>+</sup> shifts the equilibrium left (Le Chatelier, see chemical equilibrium), reducing [OH<sup>-</sup>]; so the pH falls. Both statements are correct, and II explains I.</p>'),
    stm('ie-087', 4, 'pH calculations', 'The pH of a 1 &times; 10<sup>-8</sup> M NaOH solution is 6.', 'The pH of a 1 &times; 10<sup>-8</sup> M NaOH solution is greater than 7.', 2, '<p>A base cannot make the solution acidic. Water supplies [OH<sup>-</sup>] about 10<sup>-7</sup> M, so [OH<sup>-</sup>] = (10<sup>-8</sup> + &radic;(10<sup>-16</sup> + 4 &times; 10<sup>-14</sup>))/2 = 1.05 &times; 10<sup>-7</sup>, and pH = 7.02. I is incorrect and II is correct.</p>'),
    { id: 'ie-088', type: 'mcq', level: 4, format: 'statements', exams: EX[4], sub: 'mixed counting', q: '<p>How many of the following statements are correct?</p><p>(a) NaHCO<sub>3</sub> solution is basic. (b) The pH of 10<sup>-8</sup> M HCl is below 7. (c) AlCl<sub>3</sub> solution is basic. (d) BF<sub>3</sub> is a Lewis acid.</p>', options: ['1', '2', '3', '4'], answer: 2, sol: '<p>(a) True: HCO<sub>3</sub><sup>-</sup> hydrolyses more than it ionises (pH about 8.3). (b) True: pH 6.98. (c) False: Al<sup>3+</sup> hydrolysis makes it acidic. (d) True. Three are correct.</p>', trap: 'Statement (b) surprises many: the acid gives pH just below 7, never above.' },
    P('ie-089', 4, 'titration curves', 'p1', 'After 12.5 mL of NaOH is added, the pH is', '4.74', ['2.87', '7.00', '8.72'], '<p>Half of the acid (1.25 mmol of 2.50 mmol) is converted to acetate, so [acid] = [salt] and pH = pK<sub>a</sub> = <b>4.74</b>.</p>'),
    PN('ie-090', 4, 'titration curves', 'p1', 'Find the pH at the equivalence point (25.0 mL of NaOH added). The sodium acetate is then 0.050 M.', 8.72, 0.02, '', '<p>At 25.0 mL all acid becomes acetate: 2.50 mmol in 50.0 mL = 0.050 M.</p><p>pH = 7 + &frac12;(4.74 + log 0.050) = 7 + &frac12;(4.74 - 1.30) = <b>8.72</b>.</p>', '', () => 7 + 0.5 * (4.74 + l10(0.05))),
    PN('ie-091', 4, 'titration curves', 'p1', 'Find the pH after 30.0 mL of NaOH has been added.', 11.96, 0.02, '', '<p>Excess NaOH = (30.0 - 25.0) mL &times; 0.100 M = 0.500 mmol in 55.0 mL.</p><p>[OH<sup>-</sup>] = 0.500/55.0 = 9.09 &times; 10<sup>-3</sup> M, pOH = 2.04, pH = <b>11.96</b>. (Acetate is a very weak base, so its OH<sup>-</sup> is negligible next to the excess NaOH.)</p>', '', () => 14 + l10(0.5 / 55)),
    PN('ie-092', 4, 'precipitation and pH', 'p2', 'Find the hydroxide ion concentration at which Mg(OH)<sub>2</sub> just begins to precipitate, in units of 10<sup>-5</sup> M.', 3.16, 0.02, '&times; 10<sup>-5</sup> M', '<p>Q = [Mg<sup>2+</sup>][OH<sup>-</sup>]<sup>2</sup> = K<sub>sp</sub> at the start of precipitation.</p><p>[OH<sup>-</sup>] = &radic;(10<sup>-11</sup>/0.010) = &radic;(10<sup>-9</sup>) = 3.16 &times; 10<sup>-5</sup> M. Answer: <b>3.16</b>. (This is pH 9.50.)</p>', 'Take the square root, since [OH<sup>-</sup>] is squared in K<sub>sp</sub>.', () => Math.sqrt(1e-11 / 0.01) / 1e-5),
    P('ie-093', 4, 'precipitation and pH', 'p2', 'At pH 9.0, what happens?', 'No precipitate forms because Q &lt; K<sub>sp</sub>', ['A precipitate forms because Q &gt; K<sub>sp</sub>', 'A precipitate forms because Q = K<sub>sp</sub>', 'Nothing can be said without the volume'], '<p>At pH 9, [OH<sup>-</sup>] = 10<sup>-5</sup> M. Q = [Mg<sup>2+</sup>][OH<sup>-</sup>]<sup>2</sup> = 0.010 &times; 10<sup>-10</sup> = 10<sup>-12</sup>, less than K<sub>sp</sub> = 10<sup>-11</sup>. The solution is unsaturated, so no precipitate.</p>'),
    P('ie-094', 4, 'common ion effect', 'p2', 'Adding solid NH<sub>4</sub>Cl to the solution of aqueous NH<sub>3</sub> used as the source of OH<sup>-</sup> prevents Mg(OH)<sub>2</sub> from precipitating. The reason is that', 'NH<sub>4</sub><sup>+</sup> suppresses the ionisation of NH<sub>3</sub>, so [OH<sup>-</sup>] falls and Q &lt; K<sub>sp</sub>', ['NH<sub>4</sub>Cl increases K<sub>sp</sub> of Mg(OH)<sub>2</sub>', 'NH<sub>4</sub>Cl reduces [Mg<sup>2+</sup>] by forming a gas', 'Cl<sup>-</sup> forms a complex with OH<sup>-</sup>'], '<p>NH<sub>3</sub> + H<sub>2</sub>O &#8652; NH<sub>4</sub><sup>+</sup> + OH<sup>-</sup> shifts left when NH<sub>4</sub><sup>+</sup> is added (common ion effect). With [OH<sup>-</sup>] lowered, Q for Mg(OH)<sub>2</sub> stays below K<sub>sp</sub>. K<sub>sp</sub> itself never changes with concentrations.</p>', 'The old qualitative-analysis step: group III is precipitated with NH<sub>4</sub>Cl/NH<sub>4</sub>OH.'),

    // ---------- Level 5 ----------
    nat('ie-095', 5, 'very dilute solutions', 'Find the pH of 1.0 &times; 10<sup>-7</sup> M NaOH at 25 &deg;C.', 7.21, 0.01, '', '<p>[OH<sup>-</sup>] = 10<sup>-7</sup> + x (x from water); [H<sup>+</sup>] = x. So x(10<sup>-7</sup> + x) = 10<sup>-14</sup>, giving [H<sup>+</sup>] = x = 6.18 &times; 10<sup>-8</sup> M.</p><p>pH = -log(6.18 &times; 10<sup>-8</sup>) = <b>7.21</b>.</p>', 'The answer is not 7 and not 14 - 7 = 7.', () => 14 + l10((1e-7 + Math.sqrt(1e-14 + 4e-14)) / 2)),
    nat('ie-096', 5, 'amphiprotic species', 'Find the pH of 0.10 M NaHCO<sub>3</sub> using pH = &frac12;(pK<sub>a1</sub> + pK<sub>a2</sub>) with pK<sub>a1</sub> = 6.35 and pK<sub>a2</sub> = 10.33 of carbonic acid.', 8.34, 0.02, '', '<p>HCO<sub>3</sub><sup>-</sup> is amphiprotic. [H<sup>+</sup>] = &radic;(K<sub>a1</sub>K<sub>a2</sub>), independent of concentration (when C is large enough).</p><p>pH = &frac12;(6.35 + 10.33) = <b>8.34</b>.</p>', 'pH of an amphiprotic salt does not depend on its concentration.', () => 0.5 * (6.35 + 10.33)),
    PN('ie-097', 5, 'selective precipitation', 'p3', 'Find [Cl<sup>-</sup>] remaining when Ag<sub>2</sub>CrO<sub>4</sub> just begins to precipitate, in units of 10<sup>-5</sup> M.', 1.72, 0.03, '&times; 10<sup>-5</sup> M', '<p>Ag<sub>2</sub>CrO<sub>4</sub> starts when [Ag<sup>+</sup>] = &radic;(K<sub>sp</sub>/[CrO<sub>4</sub><sup>2-</sup>]) = &radic;(1.1 &times; 10<sup>-12</sup>/0.010) = 1.05 &times; 10<sup>-5</sup> M.</p><p>[Cl<sup>-</sup>] = 1.8 &times; 10<sup>-10</sup>/1.05 &times; 10<sup>-5</sup> = 1.72 &times; 10<sup>-5</sup> M. Answer: <b>1.72</b>. So 99.8 % of the chloride is already precipitated.</p>', '', () => 1.8e-10 / Math.sqrt(1.1e-12 / 0.01) / 1e-5),
    P('ie-098', 5, 'selective precipitation', 'p3', 'As solid AgNO<sub>3</sub> is added, the first precipitate to appear is', 'white AgCl, because it needs the smaller [Ag<sup>+</sup>] (1.8 &times; 10<sup>-8</sup> M)', ['red Ag<sub>2</sub>CrO<sub>4</sub>, because its K<sub>sp</sub> is smaller (1.1 &times; 10<sup>-12</sup>)', 'red Ag<sub>2</sub>CrO<sub>4</sub>, because it has more ions per formula unit', 'both together, as both are silver salts'], '<p>AgCl begins at [Ag<sup>+</sup>] = 1.8 &times; 10<sup>-10</sup>/0.010 = 1.8 &times; 10<sup>-8</sup> M. Ag<sub>2</sub>CrO<sub>4</sub> needs 1.05 &times; 10<sup>-5</sup> M, which is nearly 600 times more. So AgCl comes first, even though its K<sub>sp</sub> number is larger, because the salts are of different types.</p>', 'You cannot compare K<sub>sp</sub> of AB and A<sub>2</sub>B directly.'),
    nat('ie-099', 5, 'buffer capacity', '1.0 L of a buffer has 0.10 mol CH<sub>3</sub>COOH and 0.10 mol CH<sub>3</sub>COONa (pK<sub>a</sub> = 4.74). How many moles of solid NaOH must be added to raise the pH to 5.74?', 0.082, 0.002, 'mol', '<p>pH - pK<sub>a</sub> = 1, so [salt]/[acid] = 10. Adding x mol NaOH: (0.10 + x)/(0.10 - x) = 10.</p><p>0.10 + x = 1.0 - 10x gives x = 0.90/11 = <b>0.082 mol</b>.</p>', 'Each mole of NaOH moves one mole from acid to salt: both quantities change by x.', () => 0.9 / 11),
    nat('ie-100', 5, 'solubility and pH', 'A salt MX (K<sub>sp</sub> = 2.0 &times; 10<sup>-10</sup>) has an anion X<sup>-</sup> that is the conjugate base of a weak acid HX (K<sub>a</sub> = 1.0 &times; 10<sup>-5</sup>). The solution is buffered at pH 5. Find the solubility of MX in units of 10<sup>-5</sup> mol L<sup>-1</sup>.', 2, 0, '&times; 10<sup>-5</sup> mol L<sup>-1</sup>', '<p>Dissolved MX: [M<sup>+</sup>] = s and total X = [X<sup>-</sup>] + [HX] = s.</p><p>Fraction as X<sup>-</sup> = K<sub>a</sub>/(K<sub>a</sub> + [H<sup>+</sup>]) = 10<sup>-5</sup>/(10<sup>-5</sup> + 10<sup>-5</sup>) = 0.5, so [X<sup>-</sup>] = 0.5s.</p><p>K<sub>sp</sub> = s &times; 0.5s gives s<sup>2</sup> = 4 &times; 10<sup>-10</sup>, s = 2 &times; 10<sup>-5</sup>. Answer: <b>2</b>. (Without protonation s would be 1.41 &times; 10<sup>-5</sup>: acid raises the solubility of salts of weak acids.)</p>', '', () => Math.sqrt(2e-10 / 0.5) / 1e-5),
    msq('ie-101', 5, 'titration curves', 'In the titration of Na<sub>2</sub>CO<sub>3</sub> with HCl, which statements are correct?', ['The first end point (at about pH 8.3) is detected by phenolphthalein', 'The second end point (at about pH 4) is detected by methyl orange', 'The volume of HCl used up to the second end point is twice that used up to the first', 'The first end point corresponds to the formation of H<sub>2</sub>CO<sub>3</sub>'], [0, 1, 2], '<p>Na<sub>2</sub>CO<sub>3</sub> + HCl &rarr; NaHCO<sub>3</sub> + NaCl (first end point, phenolphthalein, pH about 8.3); NaHCO<sub>3</sub> + HCl &rarr; H<sub>2</sub>CO<sub>3</sub> + NaCl (second end point, methyl orange). The second step needs the same moles as the first, so total volume is double. H<sub>2</sub>CO<sub>3</sub> forms at the second, not the first, end point.</p>'),
    msq('ie-102', 5, 'salt hydrolysis', 'Which of the following statements about salt hydrolysis are correct at 25 &deg;C?', ['The hydrolysis constant of a salt of a weak acid and strong base is K<sub>w</sub>/K<sub>a</sub>', 'The pH of CH<sub>3</sub>COONH<sub>4</sub> solution depends on its concentration', 'Degree of hydrolysis of CH<sub>3</sub>COONa increases on dilution', 'The pH of a salt of a weak acid and a weak base is given by 7 + &frac12;(pK<sub>a</sub> - pK<sub>b</sub>)'], [0, 2, 3], '<p>(A) True. (B) False: for a weak-acid/weak-base salt [H<sup>+</sup>] = &radic;(K<sub>w</sub>K<sub>a</sub>/K<sub>b</sub>), independent of concentration. (C) True: h = &radic;(K<sub>h</sub>/C). (D) True.</p>'),
    mk('ie-103', 5, 'common ion effect', 'Which pair of statements about the common ion effect and K<sub>sp</sub> is correct for AgCl in 0.1 M AgNO<sub>3</sub>?', 'The solubility is much lower than in water, and K<sub>sp</sub> is unchanged', ['The solubility is much lower than in water, and K<sub>sp</sub> is lowered', 'The solubility is the same as in water because K<sub>sp</sub> is fixed', 'The solubility is higher because Ag<sup>+</sup> forms a complex with Cl<sup>-</sup>'], '<p>s = K<sub>sp</sub>/[Ag<sup>+</sup>] = 1.8 &times; 10<sup>-10</sup>/0.1 = 1.8 &times; 10<sup>-9</sup> M (versus 1.3 &times; 10<sup>-5</sup> in water), because of the common ion Ag<sup>+</sup>. K<sub>sp</sub> is a constant at constant T. (In very concentrated Cl<sup>-</sup>, complexes like AgCl<sub>2</sub><sup>-</sup> can raise the solubility, but that is not the case here.)</p>'),
    stm('ie-104', 5, 'buffers', 'A buffer made of 0.5 M NH<sub>3</sub> and 0.5 M NH<sub>4</sub>Cl has pH = 14 - pK<sub>b</sub>.', 'A buffer containing 0.10 M NaH<sub>2</sub>PO<sub>4</sub> and 0.10 M Na<sub>2</sub>HPO<sub>4</sub> has pH = pK<sub>a2</sub> of phosphoric acid.', 0, '<p>I: pOH = pK<sub>b</sub> + log(1) = pK<sub>b</sub>, so pH = 14 - pK<sub>b</sub>. Correct.</p><p>II: acid H<sub>2</sub>PO<sub>4</sub><sup>-</sup> and base HPO<sub>4</sub><sup>2-</sup> in equal amounts: pH = pK<sub>a2</sub>. Correct.</p>'),
    asr('ie-105', 5, 'selective precipitation', 'In qualitative analysis, group II sulphides (CuS, CdS) are precipitated with H<sub>2</sub>S in the presence of dilute HCl, but ZnS is not.', 'Group II sulphides have much lower K<sub>sp</sub> than ZnS, so they precipitate even with the very low [S<sup>2-</sup>] present in acid.', 0, '<p>HCl suppresses ionisation of H<sub>2</sub>S (common ion H<sup>+</sup>), keeping [S<sup>2-</sup>] very low. Only sulphides with very small K<sub>sp</sub> (CuS, CdS) reach Q &gt; K<sub>sp</sub>. ZnS has a much larger K<sub>sp</sub>, so it needs the higher [S<sup>2-</sup>] of basic solution.</p>'),
    ...XI,
  ],
  gens: [
    { id: 'ie-g01', type: 'nat', level: 1, exams: EX[1], sub: 'pH of strong acid',
      make(rng) {
        const c = pick(rng, 1, 9, 1); const e = int(rng, 1, 4); const C = c * Math.pow(10, -e);
        const ans = -l10(C);
        return { q: `Find the pH of ${c} &times; 10<sup>-${e}</sup> M HCl at 25 &deg;C (log ${c} = ${l10(c).toFixed(3)}).`, answer: +ans.toFixed(2), tol: 0.01, c, e,
          sol: `<p>HCl is strong, so [H<sup>+</sup>] = ${c} &times; 10<sup>-${e}</sup> M.</p><p>pH = -log C = ${e} - log ${c} = ${e} - ${l10(c).toFixed(3)} = <b>${ans.toFixed(2)}</b>.</p>` };
      }, verify: (p) => -(Math.log10(p.c) - p.e) },
    { id: 'ie-g02', type: 'nat', level: 2, exams: EX[2], sub: 'pH of strong base',
      make(rng) {
        const c = pick(rng, 1, 9, 1) / 2; const e = int(rng, 1, 3); const n = choose(rng, [1, 2]);
        const OH = n * c * Math.pow(10, -e); const ans = 14 + l10(OH);
        const salt = n === 1 ? 'NaOH' : 'Ba(OH)<sub>2</sub>';
        return { q: `Find the pH of ${c} &times; 10<sup>-${e}</sup> M ${salt} at 25 &deg;C (assume complete ionisation).`, answer: +ans.toFixed(2), tol: 0.01, c, e, n,
          sol: `<p>[OH<sup>-</sup>] = ${n} &times; ${c} &times; 10<sup>-${e}</sup> = ${fmt(OH, 3)} M.</p><p>pOH = -log(${fmt(OH, 3)}) = ${(-l10(OH)).toFixed(2)}, pH = 14 - pOH = <b>${ans.toFixed(2)}</b>.</p>` };
      }, verify: (p) => 14 - (-Math.log10(p.n * p.c * 10 ** -p.e)) },
    { id: 'ie-g03', type: 'nat', level: 2, exams: EX[2], sub: 'pH of weak acid',
      make(rng) {
        const Ka = pick(rng, 1, 9, 1) * Math.pow(10, -int(rng, 4, 6)); const C = choose(rng, [0.01, 0.05, 0.1, 0.2, 0.5]);
        const ans = -l10(Math.sqrt(Ka * C));
        return { q: `Find the pH of ${C} M weak acid HA with K<sub>a</sub> = ${fmt(Ka, 2)}. Use [H<sup>+</sup>] = &radic;(K<sub>a</sub>C).`, answer: +ans.toFixed(2), tol: 0.02, Ka, C,
          sol: `<p>[H<sup>+</sup>] = &radic;(${fmt(Ka, 2)} &times; ${C}) = &radic;(${fmt(Ka * C, 3)}) = ${fmt(Math.sqrt(Ka * C), 3)} M.</p><p>pH = <b>${ans.toFixed(2)}</b>.</p>` };
      }, verify: (p) => 0.5 * (-Math.log10(p.Ka) - Math.log10(p.C)) },
    { id: 'ie-g04', type: 'nat', level: 2, exams: EX[2], sub: 'Ostwald dilution law',
      make(rng) {
        const a = pick(rng, 1, 5, 1); const C = choose(rng, [0.01, 0.05, 0.1, 0.2]);
        const Ka = C * (a / 100) ** 2;
        return { q: `A ${C} M solution of a weak monobasic acid is ${a} % ionised. Find K<sub>a</sub> (take 1 - &alpha; &asymp; 1). Give the answer in units of 10<sup>-6</sup>.`, answer: +(Ka / 1e-6).toPrecision(4), tol: Ka / 1e-6 * 0.01, unit: '&times; 10<sup>-6</sup>', a, C,
          sol: `<p>&alpha; = ${a}/100 = ${a / 100}. K<sub>a</sub> = C&alpha;<sup>2</sup> = ${C} &times; (${a / 100})<sup>2</sup> = ${fmt(Ka, 3)}.</p><p>In units of 10<sup>-6</sup>: <b>${fmt(Ka / 1e-6, 3)}</b>.</p>` };
      }, verify: (p) => p.C * (p.a / 100) ** 2 / 1e-6 },
    { id: 'ie-g05', type: 'nat', level: 2, exams: EX[2], sub: 'Henderson equation',
      make(rng) {
        const pKa = choose(rng, [3.75, 4.74, 4.76, 6.35, 7.21, 9.25]); const a = pick(rng, 1, 5, 1) / 10; const s = pick(rng, 1, 8, 1) / 10;
        const ans = pKa + l10(s / a);
        return { q: `A buffer contains ${a} M weak acid and ${s} M of its sodium salt, with pK<sub>a</sub> = ${pKa}. Find its pH.`, answer: +ans.toFixed(2), tol: 0.02, pKa, a, s,
          sol: `<p>pH = pK<sub>a</sub> + log([salt]/[acid]) = ${pKa} + log(${s}/${a}) = ${pKa} + (${l10(s / a).toFixed(3)}) = <b>${ans.toFixed(2)}</b>.</p>` };
      }, verify: (p) => p.pKa + Math.log10(p.s) - Math.log10(p.a) },
    { id: 'ie-g06', type: 'nat', level: 3, exams: EX[3], sub: 'salt hydrolysis',
      make(rng) {
        const pKa = choose(rng, [3.75, 4.74, 4.76, 7.21, 9.25]); const C = choose(rng, [0.01, 0.05, 0.1, 0.5]);
        const ans = 7 + 0.5 * (pKa + l10(C));
        return { q: `Find the pH of ${C} M sodium salt of a weak acid whose pK<sub>a</sub> is ${pKa}, at 25 &deg;C.`, answer: +ans.toFixed(2), tol: 0.02, pKa, C,
          sol: `<p>The anion hydrolyses: pH = 7 + &frac12;(pK<sub>a</sub> + log C) = 7 + &frac12;(${pKa} + (${l10(C).toFixed(2)})) = <b>${ans.toFixed(2)}</b>.</p>` };
      }, verify: (p) => 7 + 0.5 * p.pKa + 0.5 * Math.log10(p.C) },
    { id: 'ie-g07', type: 'nat', level: 3, exams: EX[3], sub: 'solubility product',
      make(rng) {
        const kind = int(rng, 0, 2); const s = pick(rng, 1, 9, 1) * 1e-5;
        const f = [(x) => x * x, (x) => 4 * x ** 3, (x) => 27 * x ** 4][kind];
        const salt = ['AgBr', 'PbI<sub>2</sub>', 'Al(OH)<sub>3</sub>'][kind]; const ex = ['s<sup>2</sup>', '4s<sup>3</sup>', '27s<sup>4</sup>'][kind];
        const K = f(s); const m = Math.floor(l10(K)); const mant = K / 10 ** m;
        return { q: `The molar solubility of ${salt} is ${s / 1e-5} &times; 10<sup>-5</sup> mol L<sup>-1</sup>. Find its K<sub>sp</sub> as a number multiplied by 10<sup>${m}</sup>.`, answer: +mant.toPrecision(4), tol: mant * 0.01, unit: `&times; 10<sup>${m}</sup>`, kind, s, m,
          sol: `<p>For ${salt}, K<sub>sp</sub> = ${ex}.</p><p>K<sub>sp</sub> = ${fmt(K, 3)} = ${fmt(mant, 3)} &times; 10<sup>${m}</sup>. Answer: <b>${fmt(mant, 3)}</b>.</p>` };
      }, verify: (p) => [(x) => x * x, (x) => 4 * x ** 3, (x) => 27 * x ** 4][p.kind](p.s) / 10 ** p.m },
    { id: 'ie-g08', type: 'nat', level: 3, exams: EX[3], sub: 'solubility product',
      make(rng) {
        const kind = int(rng, 0, 1); const K = pick(rng, 1, 9, 1) * Math.pow(10, kind ? -12 : -10);
        const s = kind ? Math.cbrt(K / 4) : Math.sqrt(K);
        const salt = kind ? 'Ag<sub>2</sub>CrO<sub>4</sub>' : 'AgBr'; const rel = kind ? 's = (K<sub>sp</sub>/4)<sup>1/3</sup>' : 's = &radic;K<sub>sp</sub>';
        const m = Math.floor(l10(s)); const mant = s / 10 ** m;
        return { q: `K<sub>sp</sub> of ${salt} is ${fmt(K, 2)}. Find its molar solubility as a number multiplied by 10<sup>${m}</sup> mol L<sup>-1</sup>.`, answer: +mant.toPrecision(4), tol: mant * 0.01, unit: `&times; 10<sup>${m}</sup> mol L<sup>-1</sup>`, kind, K, m,
          sol: `<p>For ${salt}: ${rel} = ${fmt(s, 3)} mol L<sup>-1</sup> = ${fmt(mant, 3)} &times; 10<sup>${m}</sup>. Answer: <b>${fmt(mant, 3)}</b>.</p>` };
      }, verify: (p) => (p.kind ? Math.cbrt(p.K / 4) : Math.sqrt(p.K)) / 10 ** p.m },
    { id: 'ie-g09', type: 'nat', level: 3, exams: EX[3], sub: 'common ion effect on solubility',
      make(rng) {
        const K = pick(rng, 1, 9, 1) * 1e-10; const c = choose(rng, [0.01, 0.05, 0.1, 0.2]);
        const s = K / c; const m = Math.floor(l10(s)); const mant = s / 10 ** m;
        return { q: `K<sub>sp</sub> of AgCl is ${fmt(K, 2)}. Find its solubility in ${c} M NaCl as a number multiplied by 10<sup>${m}</sup> mol L<sup>-1</sup>.`, answer: +mant.toPrecision(4), tol: mant * 0.01, unit: `&times; 10<sup>${m}</sup> mol L<sup>-1</sup>`, K, c, m,
          sol: `<p>[Cl<sup>-</sup>] &asymp; ${c} M (from NaCl). s = K<sub>sp</sub>/[Cl<sup>-</sup>] = ${fmt(K, 2)}/${c} = ${fmt(s, 3)} mol L<sup>-1</sup> = ${fmt(mant, 3)} &times; 10<sup>${m}</sup>. Answer: <b>${fmt(mant, 3)}</b>.</p>` };
      }, verify: (p) => p.K / p.c / 10 ** p.m },
    { id: 'ie-g10', type: 'nat', level: 3, exams: EX[3], sub: 'mixing acid and base',
      make(rng) {
        const V1 = pick(rng, 50, 150, 25); const C1 = pick(rng, 2, 8, 1) / 10; const V2 = pick(rng, 50, 150, 25); const C2 = pick(rng, 1, 4, 1) / 10;
        const nH = V1 * C1 / 1000, nO = V2 * C2 / 1000; const V = (V1 + V2) / 1000;
        const ex = nH - nO; const ans = ex > 0 ? -l10(ex / V) : 14 + l10(-ex / V);
        if (Math.abs(ex) < 1e-9) return this.make(rng);
        return { q: `${V1} mL of ${C1} M HCl is mixed with ${V2} mL of ${C2} M NaOH at 25 &deg;C. Find the pH of the mixture.`, answer: +ans.toFixed(2), tol: 0.02, V1, C1, V2, C2,
          sol: `<p>mmol H<sup>+</sup> = ${V1 * C1}, mmol OH<sup>-</sup> = ${V2 * C2}. ${ex > 0 ? 'Acid is in excess' : 'Base is in excess'}: ${fmt(Math.abs(ex) * 1000, 3)} mmol in ${V1 + V2} mL.</p><p>Concentration = ${fmt(Math.abs(ex) / V, 3)} M, so pH = <b>${ans.toFixed(2)}</b>.</p>` };
      }, verify: (p) => { const e = p.V1 * p.C1 - p.V2 * p.C2; const c = Math.abs(e) / (p.V1 + p.V2); return e > 0 ? -Math.log10(c) : 14 + Math.log10(c); } },
    { id: 'ie-g11', type: 'nat', level: 3, exams: EX[3], sub: 'buffer after adding acid',
      make(rng) {
        const a = pick(rng, 10, 30, 5) / 100; const s = pick(rng, 10, 30, 5) / 100; const x = pick(rng, 1, 8, 1) / 100; const pKa = choose(rng, [4.74, 4.76, 7.21]);
        const ans = pKa + l10((s - x) / (a + x));
        return { q: `1.0 L of buffer holds ${a} mol weak acid HA and ${s} mol of its sodium salt (pK<sub>a</sub> = ${pKa}). Find the pH after adding ${x} mol HCl (no volume change).`, answer: +ans.toFixed(2), tol: 0.02, a, s, x, pKa,
          sol: `<p>HCl converts A<sup>-</sup> to HA: acid = ${(a + x).toFixed(2)}, salt = ${(s - x).toFixed(2)} mol.</p><p>pH = ${pKa} + log(${(s - x).toFixed(2)}/${(a + x).toFixed(2)}) = <b>${ans.toFixed(2)}</b>.</p>` };
      }, verify: (p) => p.pKa + Math.log10((p.s - p.x) / (p.a + p.x)) },
    { id: 'ie-g12', type: 'nat', level: 3, exams: EX[3], sub: 'precipitation',
      make(rng) {
        const K = pick(rng, 1, 9, 1) * 1e-10; const c = choose(rng, [0.001, 0.01, 0.05]);
        const x = K / c; const m = Math.floor(l10(x)); const mant = x / 10 ** m;
        return { q: `A solution is ${c} M in Ag<sup>+</sup>. Find the minimum [Cl<sup>-</sup>] that starts precipitation of AgCl (K<sub>sp</sub> = ${fmt(K, 2)}). Give the answer as a number multiplied by 10<sup>${m}</sup> M.`, answer: +mant.toPrecision(4), tol: mant * 0.01, unit: `&times; 10<sup>${m}</sup> M`, K, c, m,
          sol: `<p>Precipitation starts when [Ag<sup>+</sup>][Cl<sup>-</sup>] = K<sub>sp</sub>.</p><p>[Cl<sup>-</sup>] = ${fmt(K, 2)}/${c} = ${fmt(x, 3)} M = ${fmt(mant, 3)} &times; 10<sup>${m}</sup>. Answer: <b>${fmt(mant, 3)}</b>.</p>` };
      }, verify: (p) => p.K / p.c / 10 ** p.m },
    { id: 'ie-g13', type: 'mcq', level: 2, exams: EX[2], sub: 'dilution of a strong acid',
      make(rng) {
        const pH0 = int(rng, 1, 3); const k = int(rng, 1, 3); const f = Math.pow(10, k);
        const ans = pH0 + k;
        const o = numOpts(rng, ans, [pH0 - k > 0 ? pH0 - k : pH0 + k + 1, pH0 + 2 * k, pH0 * k + 1], '', 3);
        return { q: `A strong acid solution has pH ${pH0}. It is diluted ${f} times with water. Its new pH is`, options: o.options, answer: o.answer, pH0, k,
          sol: `<p>Diluting ${f} times divides [H<sup>+</sup>] by ${f}, adding ${k} to the pH.</p><p>New pH = ${pH0} + ${k} = <b>${ans}</b> (valid because it stays well below 7).</p>` };
      } },
    { id: 'ie-g14', type: 'nat', level: 3, exams: EX[3], sub: 'ionic product of water',
      make(rng) {
        const Kw = pick(rng, 1, 9, 1) * Math.pow(10, -int(rng, 13, 14));
        const pH = -0.5 * l10(Kw);
        return { q: `At a certain temperature K<sub>w</sub> = ${fmt(Kw, 2)}. Find the pH of neutral water at this temperature.`, answer: +pH.toFixed(2), tol: 0.01, Kw,
          sol: `<p>Neutral: [H<sup>+</sup>] = &radic;K<sub>w</sub> = ${fmt(Math.sqrt(Kw), 3)} M.</p><p>pH = &frac12;pK<sub>w</sub> = <b>${pH.toFixed(2)}</b>.</p>` };
      }, verify: (p) => -Math.log10(Math.sqrt(p.Kw)) },
    ...XGN,
  ],
};
